INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (12, 1, 54, 1, 3, 2, 1, 1, 1, 'Alhamdulillah sidang pada hari ini berjalan Dengan lancar', '2023-12-10 22:50:58', '2023-12-22 13:30:36');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (13, 1, 239, 1, 2, 1, 1, 1, 1, '<p style=\"margin:0\">Sidang dilaksanakan tepat waktu dan berjalan dengan lancar.</p><p style=\"margin:0\">Dosen pembimbing dapat menghadiri sidang begitu juga dosen penguji. Meskipun ada satu dosen penguji yang tidak bisa hadir, namun hal baiknya dosen penguji yang tidak dapat hadir tersebut ada penggantinya.</p>', '2023-12-10 22:50:59', '2023-12-22 12:42:17');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (14, 1, 266, 17, 1, 10, 1, 1, 1, '<p style=\"margin:0\">Report of Defense</p><p style=\"margin:0\">Jenis: Pre Defense</p><p style=\"margin:0\">Hari dan tanggal: Jum\'at, 22 Desember 2023</p><p style=\"margin:0\">Waktu: 07.15 WIB</p><p style=\"margin:0\">Tempat: Perpustakaan FPTE</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Alur waktu:</p><p style=\"margin:0\">- 07.15 WIB: Pembukaan sidang</p><p style=\"margin:0\">- 07.20 WIB: Presentasi hasil penelitian</p><p style=\"margin:0\">- 07.30 WIB: Sesi tanya jawab, kritik, dan saran</p><p style=\"margin:0\">- 08.10 WIB: Penutupan sidang</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Kritik dan saran:</p><p style=\"margin:0\">- Diskusi bersama Dosen Pembimbing terkait penamaan judul penelitian</p><p style=\"margin:0\">- Menyertakan metode dan hasil penelitian pada bagian Abstrak</p><p style=\"margin:0\">- Deskripsi dan penjelasan untuk pemanggilan gambar sebelum ditampilkan</p><p style=\"margin:0\">- Penjelasan singkat terkait penelitian sebelumnya</p><p style=\"margin:0\">- Penyesuaian pada simpulan poin ke-1</p><p style=\"margin:0\">- Rata kiri-kanan pada bagian Lampiran</p>', '2023-12-13 16:19:37', '2024-01-16 08:18:57');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (15, 1, 183, 1, 3, 1, 1, 1, 1, '<p style=\"margin:0\"><br></p>', '2023-12-14 08:12:18', '2023-12-22 19:49:46');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (16, 1, 76, 1, 4, 3, 1, 1, 1, '<p style=\"margin:0\">Pertanyaan dari Pak Iwan Kustiawan, Ph.D sebagai penguji:</p><p style=\"margin:0\">Apa gagasan utama pembuatan aplikasi yang dirancang didalam skripsi?</p><p style=\"margin:0\">Bagaimana cara konsensus tercapai diantara para ahli yang berkaitan dengan pengujian aplikasi?</p><p style=\"margin:0\">Saran dari Pak Iwan Kustiawan, Ph.D:</p><p style=\"margin:0\">Buatkan petunjuk peguna untuk memudahkan penggunaan aplikasi.</p><p style=\"margin:0\">Jadikan aplikasi bermanfaat secara lebih agar dapat diaplikasikan tidak hanya pada peserta didik, tapi pada mahasiswa di lingkungan perkuliahan juga.</p><p style=\"margin:0\">Pertanyaan dari Bu Prof. Dr. Budi Mulyanti, M.Si sebagai penguji:</p><p style=\"margin:0\">Faktor apa yang membuat pengerjaan aplikasi menjadi begitu lama dan apa saja kendala yang dialami?</p><p style=\"margin:0\">Saran dari Bu Prof. Dr. Budi Mulyanti, M.Si:</p><p style=\"margin:0\">Ganti penggunaan titik ke koma pada bilangan desimal.</p><p style=\"margin:0\">Ganti beberapa kalimat pada flowchart agar lebih jelas menerangkan apa yang dimaksudkan dalam flowchart itu sendiri.</p><p style=\"margin:0\">Lebih jelaskan kembali terkait metode-metode yang digunakan seperti delphi dan SDLC waterfall di bagian Abstrak.</p>', '2023-12-14 13:01:32', '2023-12-23 14:07:06');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (17, 1, 217, 1, 4, 2, 1, 1, 1, '<p style=\"margin:0\">1. menjelasakan latar belakang dengan spesifik lagi.</p><p style=\"margin:0\">2. menuliskan penelitian ini sebagai penelitian pendahuluan untuk penelitian yang lain,&nbsp; tentang kesiapan kerja SMK.&nbsp;</p><p style=\"margin:0\">3. memperbaiki flowchart tentang prosedur penelitian.&nbsp;</p><p style=\"margin:0\">4. memperbaiki penulisan kata yang typo.</p><p style=\"margin:0\">5. menambahkan rekomendasi tentang soft skill untuk siswa belajar.</p><p style=\"margin:0\">6. memperbaiki letak nama gambar pada kerangka berfikir.&nbsp;</p>', '2023-12-14 13:15:46', '2023-12-23 22:21:49');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (18, 1, 44, 17, 1, 11, 1, 1, 1, '<p style=\"margin:0\">Sidang pre-defense dilaksanakan di hari Jum\'at tanggal 22 Desember 2023 yang dihadiri oleh Pak Enjang, Pak Resa, dan Pak Aip sebagai Dosen Penguji dan Ibu Arjuni sebagai Dosen Pembimbing I. Pak Fahmi sebagai Dosen Pembimbing II berhalangan hadir dikarenakan harus menjadi Dosen Penguji Mahasiswa bernama Ilham di ruang Perpustakaan TE. Sidang pre-defense dilaksanakan dengan baik, adapun catatan dari Dosen Penguji terdapat beberapa hal yang perlu diperbaiki, mencakup:</p><p style=\"margin:0\">1.&nbsp;<span style=\"font-family: Calibri, sans-serif; font-size: 11pt; color: inherit;\">Perbaikan dari Pak Enjang, penggunaan frasa “blok diagram” yang benar adalah “diagram blok”</span><span style=\"color: inherit; font-size: 1rem;\">&nbsp;(Pak Enjang) =&gt; terdapat di bagian daftar gambar halaman xi, 7, 24, 27, 28, dan 29.</span></p><p style=\"margin:0\">2. Penyederhanaan kalimat untuk tujuan penelitian poin ke-dua (Pak Aip)</p><p style=\"margin:0\">3. Penghapusan frasa \"yang mana\" setelah kata \"objek\" pada halaman 5 (Pak Aip)</p><p style=\"margin:0\">4. Perbaikan frasa \"GNURadio\" menjadi dipisah \"GNU Radio\" pada halaman 18 (Pak Aip)</p><p style=\"margin:0\"><span style=\"font-size: 11pt; line-height: 15.6933px; font-family: Calibri, sans-serif;\">5. Perbaikan dari Pak Enjang: huruf P untuk kata “Python” seharusnya menggunakan Huruf kapital pada halaman 19 .</span></p><p style=\"margin:0\"><span style=\"font-size: 11pt; line-height: 15.6933px; font-family: Calibri, sans-serif;\"><span style=\"font-family: &quot;Source Sans Pro&quot;, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;; font-size: 16px;\">6.&nbsp;</span></span><span style=\"font-family: Calibri, sans-serif; font-size: 11pt; color: inherit;\">Perbaikan dari Aip: untuk menyeragamkan penggunaan angka penting dalam TA</span><span style=\"color: inherit;\">&nbsp;yang ada di halaman 37, 48, 49, 50, 51, 52, 56, 58, 59, 61, 62, 63,64 dan 66.</span></p><p style=\"margin:0\"><span style=\"font-size: 11pt; line-height: 15.6933px; font-family: Calibri, sans-serif;\">7. Perbaikan dari Pak Aip, dikarenakan tidak adanya pemanggilan gambar pada halaman 44</span></p><p style=\"margin:0\"><span style=\"font-size: 11pt; line-height: 15.6933px; font-family: Calibri, sans-serif;\">8.&nbsp;<span style=\"font-size: 11pt; line-height: 15.6933px;\">Perbaikan dari Pak Aip, pengunaan angka dan satuan pada “2,5MHz” seharusnya dipisah menjadi “2,5 MHz” yang ada di halaman 44.</span></span></p><p style=\"margin:0\"><span style=\"font-size: 11pt; line-height: 15.6933px; font-family: Calibri, sans-serif;\"><span style=\"font-size: 11pt; line-height: 15.6933px;\">9.&nbsp;<span style=\"font-size: 11pt; line-height: 15.6933px;\">Perbaikan dari Pak Aip, pengunaan angka dan satuan pada “2,4GHz” seharusnya dipisah menjadi “2,4 GHz” yang ada di halaman 44.</span></span></span></p><p style=\"margin:0\"><span style=\"font-size: 11pt; line-height: 15.6933px; font-family: Calibri, sans-serif;\"><span style=\"font-size: 11pt; line-height: 15.6933px;\"><span style=\"font-size: 11pt; line-height: 15.6933px;\">10.&nbsp;<span style=\"font-size: 11pt; line-height: 15.6933px;\">Perbaikan dari Pak Aip: pemilihan kata, yang awalnya “Menggambarkan” menjadi “Menunjukkan” yang ada di&nbsp; halaman 46.</span></span></span></span></p><p style=\"margin:0\"><span style=\"font-size: 11pt; line-height: 15.6933px; font-family: Calibri, sans-serif;\"><span style=\"font-size: 11pt; line-height: 15.6933px;\"><span style=\"font-size: 11pt; line-height: 15.6933px;\"><span style=\"font-size: 11pt; line-height: 15.6933px;\">11.&nbsp;<span style=\"font-size: 11pt; line-height: 15.6933px;\">Perbaikan dari Pak Aip yang awalnya “Pada Gambar 4.27” menjadi “Gambar 4.27” yang ada di halaman 46, begitu juga pada halaman 31,&nbsp;</span><span style=\"font-size: 11pt; line-height: 15.6933px;\"><span style=\"font-size: 11pt; line-height: 15.6933px;\">“Pada Gambar 4.31” menjadi “Gambar 4.31”, lalu halaman 49 \"Pada Gambar 4.33\" menjadi \"Gambar 4.33\"</span></span></span></span></span></span></p><p style=\"margin:0\"><span style=\"font-size: 11pt; line-height: 15.6933px; font-family: Calibri, sans-serif;\"><span style=\"font-size: 11pt; line-height: 15.6933px;\"><span style=\"font-size: 11pt; line-height: 15.6933px;\"><span style=\"font-size: 11pt; line-height: 15.6933px;\"><span style=\"font-size: 11pt; line-height: 15.6933px;\"><span style=\"font-size: 11pt; line-height: 15.6933px;\">12.&nbsp;<span style=\"font-size: 11pt; line-height: 15.6933px;\">Perbaikan dari Aip: kalimat “jarak non-ambigu nya 60 m” menjadi “jarak non-ambigu 60 m” yang ada di halaman 56.</span></span></span></span></span></span></span></p><p style=\"margin:0\"><span style=\"font-size: 11pt; line-height: 15.6933px; font-family: Calibri, sans-serif;\"><span style=\"font-size: 11pt; line-height: 15.6933px;\"><span style=\"font-size: 11pt; line-height: 15.6933px;\"><span style=\"font-size: 11pt; line-height: 15.6933px;\"><span style=\"font-size: 11pt; line-height: 15.6933px;\"><span style=\"font-size: 11pt; line-height: 15.6933px;\"><span style=\"font-size: 11pt; line-height: 15.6933px;\">13.&nbsp;<span style=\"font-size: 11pt; line-height: 15.6933px;\">Perbaikan dari Aip: kalimat “nilai Ru nya” menjadi “nilai Ru” yang di halaman 56.</span></span></span></span></span></span></span></span></p><p style=\"margin:0\"><span style=\"font-size: 11pt; line-height: 15.6933px; font-family: Calibri, sans-serif;\">14. Kesesuaian banyaknya poin yang dibahas di bagian kesimpulan dengan tujuan penelitian ( Pak Aip)</span></p><p style=\"margin:0\"><span style=\"font-size: 11pt; line-height: 15.6933px; font-family: Calibri, sans-serif;\"><span style=\"font-size: 11pt; line-height: 15.6933px;\"><span style=\"font-size: 11pt; line-height: 15.6933px;\"><span style=\"font-size: 11pt; line-height: 15.6933px;\"><span style=\"font-size: 11pt; line-height: 15.6933px;\"><span style=\"font-size: 11pt; line-height: 15.6933px;\"><span style=\"font-size: 11pt; line-height: 15.6933px;\"><br></span><br></span><br></span><br style=\"font-size: 14.6667px;\"></span><br></span><br></span><br></span><span style=\"color: inherit;\"><br></span></p><p style=\"margin:0\"><span style=\"font-size: 11pt; line-height: 15.6933px; font-family: Calibri, sans-serif;\"><br></span><br></p><p style=\"margin:0\"><br></p>', '2023-12-14 16:36:56', '2023-12-26 22:06:20');
