INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (29, 1, 15, 20, 3, 2, 1, 1, 1, '<p style=\"margin:0\">Saya telah melaksanakan sidang Pre-Defense pada Kamis, 4 Januari 2024 dengan kehadiran 3 dosen penguji dan dosen pembimbing</p><p style=\"margin:0\"><br></p><p style=\"margin:0\"><br></p>', '2023-12-23 15:52:42', '2024-01-05 08:50:03');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (30, 1, 71, 20, 2, 2, 1, 1, 1, '<p style=\"margin:0\">Xx</p>', '2023-12-26 03:56:42', '2024-01-08 11:22:00');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (31, 1, 67, 20, 2, 1, 1, 1, 1, 'Pada sidang <i>pre-defense </i>kali ini saya sangat bersyukur dapat diuji oleh para dosen yang sangat ahli di bidangnya bisa menguji saya pada kesempatan yang sangat penting ini. Banyak sekali masukan dari bapak dan ibu dosen penguji yang dapat memperbaiki penulisan tugas akhir saya sehingga menjadi lebih baik lagi seperti penulisan abstrak yang terlalu panjang, penulisan kalimat berbahasa inggris, penulisan rumus, penulisan dalam mengutip referensi, penjelasan flowchart pada bab 3, serta masalah utama pada penelitian yang perlu dikemas ulang sehingga menjadi sajian yang lebih baik dan sesuai terhadap standar yang telah ditetapkan UPI. Oleh karena itu penulis selanjutnya akan memperbaiki apa saja yang telah bapak dan ibu dosen diskusikan selama sidang sehingga tugas akhir saya akan menjadi lebih baik lagi. Kemudian penulis juga ingin mengucapkan terimakasih sebesar-besarnya pada para dosen penguji dan juga pembimbing yang telah membantu penulis hingga sampai pada titik ini dan berhasil melaluinya dengan baik.', '2023-12-26 12:55:19', '2024-01-06 10:55:21');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (32, 1, 47, 20, 2, 3, 1, 1, 1, '<p style=\"margin:0\">Sidang telah dilaksanakan pada hari Kamis, 04 Januari 2023 dan dihadiri oleh dosen pembimbing serta 3 dosen penguji&nbsp;</p>', '2023-12-28 11:09:09', '2024-01-06 18:40:08');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (33, 1, 57, 20, 3, 1, 1, 1, 1, '<p style=\"margin:0\">Pre-defense telah dilaksanakan pada tanggal 4 Januari 2024 pukul 09.00</p>', '2023-12-28 20:57:26', '2024-01-09 18:01:14');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (34, 1, 53, 20, 3, 3, 1, 1, 1, '<p style=\"margin:0\">Sidang tertutup skripsi telah dilaksanakan pada tanggal 4 Januari 2024 pukul 09.15 hingga 10.45. Sidang tertutup dihadiri oleh Qintar Alifah Ristiana sebagai peserta sidang. Dr. Aip Saripudin, M.T. sebagai dosen pembimbing. Bapak Didin Wahyudin, Ph.D., Dr. Erik Haritman, S.Pd., M.T., Dr. Ir. H. Dadang Lukman Hakim, M.T. sebagai penguji. Adapun beberapa masukan dari penguji pada bagian penulisan dan rekomendasi pengujian alat telah diterima serta akan didiskusikan kembali bersama dosen pembimbing.</p>', '2023-12-28 20:58:51', '2024-01-09 17:43:23');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (35, 1, 23, 22, 2, 3, 1, 1, 1, '<p style=\"margin:0\">Pre defense dilaksanakan pada tanggal 9 Januari 2024 pada pukul 08.00 - 09.00 WIB yang bertempat di Lab. Telkom Lt.5 gedung A FPTK. Yang di hadiri oleh dosen penguji yaitu Bapak&nbsp;Dr. Aip Saripudin, S.Si, M.T. dan Bapak&nbsp;Didin Wahyudin, M.T., Ph.D. Dan juga dihadiri oleh dosen pembimbing 1 yaitu Ibu&nbsp;Ir. Hj. Arjuni Budi P, M.T. Dan dosen pembimbing 2 yaitu Bapak&nbsp;Alit Rahmat, M.Pd. Yang kemudian acara dibuka oleh&nbsp;<span style=\"color: inherit; font-size: 1rem;\">Ibu&nbsp;Ir. Hj. Arjuni Budi P, M.T.</span><span style=\"color: inherit; font-size: 1rem;\">&nbsp;dilanjutkan dengan persentasi hasil sidang skripsi Lina Puspitasari 1905290 dengan judul \"</span><span style=\"color: inherit; font-size: 1rem;\">Rancang Bangun GPS (Global Positioning system) tracking dengan Ublox NEO-6M GPS Module berbasis Telegram pada Smart Vest jogging bagi Tunanetra\" setelah itu dilakukan sesi tanya jawab dengan dosen penguji yang di awali oleh&nbsp;</span><span style=\"color: inherit; font-size: 1rem;\">Bapak&nbsp;Dr. Aip Saripudin, S.Si, M.T. kemudian dilanjutkan sesi tanya jawab dengan&nbsp;</span><span style=\"color: inherit; font-size: 1rem;\">Bapak&nbsp;Didin Wahyudin, M.T., Ph.D. kemudian penutupan persentasi sidang skripsi pada pukul 09.00 WIB.</span></p>', '2024-01-01 16:58:09', '2024-01-10 08:47:53');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (36, 1, 32, 22, 3, 1, 1, 1, 1, '<p style=\"margin:0\">Pre defense telah dilaksanakan pada tanggal 9 Januari 2024.</p>', '2024-01-02 17:05:28', '2024-01-09 18:03:51');
