INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (43, 1, 2, 22, 3, 3, 1, 1, 1, '<p style=\"margin:0\">Predefense</p><p style=\"margin:0\">Waktu: Selasa, 9 Januari 2024 (10.00)</p><p style=\"margin:0\">Dosen Penguji: I<span style=\"color: inherit; font-size: 1rem;\">wan Kustiawan,&nbsp;</span><span style=\"color: inherit; font-size: 1rem;\">Muhammad Adli Rizqullah</span></p><p style=\"margin:0\"><span style=\"color: inherit; font-size: 1rem;\">Dosen Pembimbing :&nbsp;</span><span style=\"color: inherit; font-size: 1rem;\">Arjuni Budi Pantjawati</span></p><p style=\"margin:0\"><span style=\"color: inherit; font-size: 1rem;\"><br></span></p><p style=\"margin:0\"><span style=\"color: inherit; font-size: 1rem;\">Sidang tertutup dimulai pukul 10.00 dan dibuka oleh Bu Arjuni. Kemudian dilakukan presentadi penelitian \"</span><span style=\"color: inherit; font-size: 1rem;\">Forecasting Perkembangan Teknologi Jaringan 5G di Indonesia\"&nbsp;</span><span style=\"color: inherit; font-size: 1rem;\">dengan overview pembahasan latar belakang, penelitian sebelumnya, metode penelitian, hasil pembahasan, kesimpulan. Setelah itu, dilakukan sesi tanya jawab oleh dosen penguji dan ditutup oleh Bu Arjuni.</span></p><p style=\"margin:0\"><span style=\"color: inherit; font-size: 1rem;\"><br></span></p>', '2024-01-03 16:56:06', '2024-01-12 09:52:08');
