INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (66, 1, 12, 26, 2, 1, 1, 1, 1, '<p style=\"margin:0\">Sidang Pre-Defense dilaksanakan di hari Rabu tanggal 17 Januari 2024 dihadiri oleh dosen pebimbing yaitu Pak Iwan Kustiawan dan Bu Silmi Ath Thahirah dan dosen penguji yaitu Pak Enjang A. Juanda, Pak Agus Heri, dan Pak Wasimudin Surya<br><br>Adapun catatan dari dosen penguji yaitu:<br>1. mengubah judul dari teknologi menjadi aplikasi<br>2. menambahkan teori dasar pengenalan wajah pada bab 2<br>3. menambahkan paragraf rekomendasi jurnal<br>4. memperbaiki urutan pada sub bab 2<br>5. memperbaiki judul pada tabel<br><br>catatan dari dosen pebimbing yaitu:&nbsp;<br>1. mengubah judul menjadi&nbsp;<span style=\"color: inherit; font-size: 1rem;\">Rancang Bangun Aplikasi Pengenalan Wajah Berbasis Computer\nVision Untuk Meningkatkan Keamanan Penjemputan Siswa<br>2. menambahkan teori dasar pengenalan wajah<br></span></p><p class=\"MsoNormal\"><o:p></o:p></p>', '2024-01-12 11:13:23', '2024-01-19 07:20:46');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (67, 1, 182, 3, 6, 2, 1, 1, 1, '<p style=\"margin:0\">Alhamdulillah telah pre-defense</p>', '2024-01-12 12:49:59', '2024-01-22 16:02:24');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (68, 1, 42, 26, 2, 2, 1, 1, 1, '<p style=\"margin:0\">Sidang tanggal 17Januari 2024. Penguji yang hadir adalah Pak Prof. Jaja Kustija, Pak Bambang Trisno,&nbsp; dan Pak Saripudin. Pembimbing yang hadir adalah Pak Elih Mulyana dan Pak Yadi Mulyadi. Sidang dimulai pukul 08.03 sampai dengan 09.01. Sidang dibuka oleh Pak Elih dan ditutup oleh saya sendiri.<br></p>', '2024-01-12 13:39:55', '2024-01-19 19:52:51');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (69, 1, 274, 3, 5, 3, 1, 1, 1, '<p style=\"margin:0\">Pahami mengenai project rangkaian TRIAC dan LDR</p><p style=\"margin:0\">Tambahkan penelitian yang relevan di bab 2, kaitkan dengan penelitian yang kamu lakukan</p><p style=\"margin:0\">Subjek penelitian, alasan dipilih 4 subjek penelitian kenapa?</p><p style=\"margin:0\">Tambahkan referensi jurnal di kisi-kisi observasi dan wawancara</p><p style=\"margin:0\">Aspek pjbl tidak terlihat, jelaskan project based, tambahkan modul ajar atau penjelasan project</p><p style=\"margin:0\">Kesalahan konsep, harus ada penjelasan</p>', '2024-01-12 23:03:24', '2024-01-19 03:08:23');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (70, 1, 235, 3, 3, 2, 1, 1, 1, '<p style=\"margin:0\">Saya telah melaksanakan sidang Pre-Defense pada Kamis, 18 Januari 2024</p>', '2024-01-13 08:40:13', '2024-01-19 12:00:46');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (71, 1, 20, 30, 2, 11, 1, 1, 1, '<p style=\"margin:0\">Sidang tertutup telah berjalan, dihadiri 3 dosen penguji dan 1 dosen pembimbing</p>', '2024-02-22 10:57:53', '2024-04-25 15:25:45');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (72, 1, 38, 30, 3, 10, 1, 1, 1, '<p style=\"margin:0\">Sudah sidang dengan penguji hadir semua</p>', '2024-03-29 11:09:44', '2024-04-19 10:47:20');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (73, 1, 277, 30, 4, 11, 1, 1, 1, '<p style=\"margin:0\">Sidang sudah dilaksanakan dan dosen penguji hadir semua.</p>', '2024-03-29 14:53:39', '2024-04-19 21:00:43');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (74, 1, 66, 30, 3, 11, 1, 1, 1, '<p style=\"margin:0\">Sidang Pre-Defense terlaksana pada tanggal 19 April 2024, pukul 09.34 - 10.40 di ruangan dosen 12-13 DPTE.</p><p style=\"margin:0\">Kehadiran dosen pembimbing:</p><ol><li>(Tidak hadir) Prof. Dr. Hj. Budi Mulyani, M.Si. : Memiliki kegiatan lain yang harus dihadiri</li><li>(Hadir) Silmi Ath Thahirah Al Azhima, S.T., M.T. : Hadir dan menjadi moderator sidang</li></ol><p style=\"margin:0\">Kehadiran dosen penguji:</p><ol><li>(Hadir) Didin Wahyudin, S.Pd., MT., Ph.D.</li><li>(Hadir) Dr. Erik Haritman, S.Pd., M.T.</li><li>(Tidak hadir) Mariya Al Qibtiya, S.Si., M.T. : Sakit</li></ol><p style=\"margin:0\">Sidang berjalan dengan lancar dengan beberapa masukan dari dosen penguji:</p><ol><li>Buat judul menjadi lebih spesifik pada apa yang diteliti</li><li>Sertakan juga jenis regresi apa yang digunakan dan bagaimana cara menggunakannya</li><li>Hindari overclaim pada riset yang dilakukan</li></ol><p style=\"margin:0\"><br></p>', '2024-04-01 08:51:56', '2024-04-20 23:03:49');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (75, 1, 269, 30, 1, 11, 1, 1, 1, '<p style=\"margin:0\">Alhamdulillah telah selesai melaksanakan sidang tertutup pre defense. Dosen penguji hadir seluruhnya, dan ada beberapa revisi pada skripsi saya</p>', '2024-04-02 12:08:10', '2024-04-21 16:17:20');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (76, 1, 142, 30, 1, 10, 1, 1, 1, '<p style=\"margin:0\">Sidang sudah dilaksanakan, penguji hadir semua.</p>', '2024-04-03 17:48:34', '2024-04-19 14:37:45');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (77, 1, 94, 30, 2, 10, 1, 1, 1, '<p style=\"margin:0\">Sidang telah dilaksanakan dengan lancar,<br>pembimbing hadir: Wasimudin Surya Saputra, S.T., M.T.<br>penguji hadir :<br>Prof. Dr. H. Jaja Kustija, M.Sc.<br>Dr. Elih Mulyana, M.Si.<br>Dr. Bambang Trisno, MSIE.</p>', '2024-04-07 22:11:01', '2024-04-25 11:34:07');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (78, 1, 82, 30, 4, 10, 1, 1, 1, '<p style=\"margin:0\">Saya sudah melaksanakan sidang skripsi pada pukul 10.00-11.00 dengan dosen penguji yang hadir hanya dua yaitu Bapak Tasma Sucita dan Bapak Maman Somantri, sedangkan Bapak Wawan Purnama tidak hadir</p>', '2024-04-08 11:18:23', '2024-04-19 21:32:06');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (79, 1, 257, 30, 4, 2, 1, 1, 1, '<p style=\"margin:0\">Sidang sudah dilaksanakan dan dosen penguji hadir semua.</p>', '2024-04-13 00:56:17', '2024-04-19 20:57:45');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (80, 1, 70, 30, 7, 10, 1, 1, 1, '<p style=\"margin:0\">Sidang telah terlaksana dan dosen pembimbing serta semua dosen penguji telah hadir&nbsp;</p>', '2024-04-14 11:15:10', '2024-04-22 12:23:32');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (81, 1, 258, 30, 4, 1, 1, 1, 1, 'Alhamdulillah sidang berjalan dengan lancar, Pembimbing I berkenan hadir, 2 orang penguji hadir, 1 orang berhalangan hadir. Alhamdulillah, semoga semua selalu diberi kesehatan. Aamiin', '2024-04-16 14:21:46', '2024-04-20 04:42:39');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (82, 1, 213, 30, 1, 2, 1, 1, 1, '<p style=\"margin:0\">Saya telah melakukan pre-defense pada hari Jumat 19 April 2024&nbsp;</p>', '2024-04-16 15:00:28', '2024-04-20 10:13:05');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (83, 1, 92, 30, 3, 2, 1, 1, 1, '<p style=\"margin:0\">Sidang dibuka oleh Bapak Muhammad Adli Rizqullah pada pukul 09:30 dan ditutup oleh Bapak Muhammad Adli Rizqullah pukul 10:20. Sidang dihadiri oleh semua penguji dan pembimbing.</p><p style=\"margin:0\">terdiri dari 2 sesi, yaitu sesi pertama yaitu presentasi selama 10 menit dan sesi ke dua yaitu tanya jawab selama 40 menit.</p><p style=\"margin:0\">Revisi yang disampaikan oleh Bapak Agus Heri adalah, referensi mengenai perbandingan implementasi hardware dan software, memasukan rangkaian AES konvensional dan sumbernya.</p><p style=\"margin:0\">Revisi yang disampaikan oleh Bu Siscka Elvyanti adalah untuk memperbaiki kalimat permutasi pada proses subbyte transformation.</p><p style=\"margin:0\">Revisi yang disampaikan oleh Bu Arjuni Budi Pantjawati adalah untuk menggunakan nomor gambar dan tabel pada penjelasannya, memperbaiki gambar Flowchart cara kerja AES, dan memberikan penjelasan mengenai trade off pada sistem apakah masih bisa ditoleransi atau tidak.</p>', '2024-04-16 15:35:03', '2024-04-19 11:49:36');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (84, 1, 240, 30, 2, 1, 1, 1, 1, '<p style=\"margin:0\">Sidang telah terlaksana dan semua dosen penguji dan dosen pembimbing hadir semua. Terimakasih</p>', '2024-04-17 10:00:48', '2024-04-22 12:05:16');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (85, 1, 302, 35, NULL, NULL, NULL, 1, NULL, NULL, '2024-04-25 09:53:42', '2024-05-30 11:54:19');
