INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (88, 1, 293, 36, 4, 2, 1, 1, 1, '<p style=\"margin:0\"><a href=\"https://drive.google.com/file/d/1lVPIlfeY3ityWshmmvVqvw_5ANu2TQ4B/view?usp=drivesdk\" target=\"_blank\">https://drive.google.com/file/d/1lVPIlfeY3ityWshmmvVqvw_5ANu2TQ4B/view?usp=drivesdk</a></p>', '2024-05-13 19:53:00', '2024-05-17 20:01:57');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (89, 1, 29, 36, 1, 11, 1, 1, 1, '<p style=\"margin:0\">Report Pre-Defense</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Sidang pre-defense dimulai pada pukul 07.10-08.10 WIB. Sidang dihadiri oleh Prof. Dr. Hj. Budi Mulyanti, M.Si. selaku dosen pembimbing 1 serta Prof. Dr. Tuti Suartini,M.Pd, Siscka Elvyanti, M.T, Muhammad Adli Rizqulloh, S.Pd, M.T selaku dosen penguji. Terdapat revisi yang diberikan oleh dosen penguji seperti dalam hal kepenulisan skripsi. Sidang berjalan dengan cukup lancar dan diakhiri dengan doa bersama.</p>', '2024-05-14 06:11:00', '2024-05-19 11:43:17');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (90, 1, 282, 36, 1, 10, 1, 1, 1, '<p style=\"margin:0\">Saya telah melakukan sidang tertutup pada hari Jumat 17 Mei 2024 di Ruangan Perpustakaan. Dengan dosen penguji Bapak Yadi Mulyadi, Bapak Wasimudin Surya Saputra, dan Bapak Bambang Trisno.&nbsp;</p>', '2024-05-14 08:26:40', '2024-05-17 12:49:45');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (91, 1, 307, 36, 3, 10, 1, 1, 1, '<p style=\"margin:0\">telah melakukan perbaikan skripsi yang sudah di sampaikan oleh penguji,https://drive.google.com/file/d/1Ipv6aqMWbbwsHUCPVGcllXaGh8oirlPr/view?usp=sharing<a href=\"https://drive.google.com/file/d/1Ipv6aqMWbbwsHUCPVGcllXaGh8oirlPr/view?usp=sharing\" target=\"_blank\">perbaikan pre defense</a></p>', '2024-05-14 10:29:32', '2024-06-21 13:17:27');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (92, 1, 11, 36, 3, 2, 1, 1, 1, '<p style=\"margin:0\">Saya sudah menyelesaikan sidang tertutup pada hari Jumat, 17 Mei 2024, dengan dosen penguji:</p><p style=\"margin:0\">Wasimudin Surya Saputra<br>Maman Somantri<br>Aip Saripudin<br></p>', '2024-05-14 14:22:31', '2024-05-17 10:28:50');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (93, 1, 276, 36, 1, 2, 1, 1, 1, '<p style=\"margin:0\">Saya telah menyelesaikan pre defense pada tanggal 17 Mei 2024 dengan penguji</p><p style=\"margin:0\">Bapak Maman Somantri , dan Bapak Aip Sarippudin</p>', '2024-05-14 14:24:21', '2024-05-18 22:49:23');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (94, 1, 13, 36, 2, 1, 1, 1, 1, '<p style=\"margin:0\">Pada pre-defense didapatkan hasil sebagai berikut:</p><p style=\"margin:0\">1. Judul yang diteliti tidak sesuai dengan hasil yang diteliti sehingga penggantian judul menjadi \"Efisiensi Keamanan Siber Menggungakan Advanced Encryption Standard untuk Melindungi Smart Home\"</p><p style=\"margin:0\">2. Latar belakang yang diteliti tidak sesuai dengan hasil penelitian sehingga direvisi kembali latar belakang yang sudah ditulis</p><p style=\"margin:0\">3. Gambar dan tabel pada skripsi tidak sesuai sehingga akan dilakukan penomoran ulang pada gambar dan tabel</p><p style=\"margin:0\">4. Pada bagian abstrak seharusnya tidak wajib dijelaskan secara detail data yang sudah didapat sehingga menuliskan kembali abstrak dengan data hasil keseluruhan saja</p><p style=\"margin:0\">5. Dikarenakan AES tidak termasuk lightweight cryptography sehingga penyusunan kembali kajian pustaka dan judul skripsi</p><p style=\"margin:0\">6. Dikarenakan tidak dilakukan pengujian gangguan untuk keamanan sibernya dan hanya dilakukan pengujian efisiensi keamanan siber maka latar belakang yang ditulis seharusnya tentang efisiensi keamanan siber yang sudah diteliti dan pada kajian pustaka kembali ditulis mengenai efisiensi kemanan siber pada sistem smart home</p>', '2024-05-14 14:30:59', '2024-05-21 22:59:53');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (95, 1, 278, 36, 1, 1, 1, 1, 1, '<p style=\"margin:0\">Alhamdulillah sidang berjalan dengan lancar. Semua dosen penguji hadir pada persidangan ini dan memberikan banyak masukan dan usulan terhadap penelitian ini.</p>', '2024-05-14 17:47:55', '2024-05-19 09:28:30');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (96, 1, 75, 36, 4, 10, 1, 1, 1, '<p style=\"margin:0\">Saya telah menyelesaikan sidang pre-defense pada tanggal 17 Mei 2024 dengan sidang penguji&nbsp; Prof. Dr.&nbsp;<span style=\"color: inherit; font-size: 1rem;\">Jaja Kustija, M.Sc, Dr. Bambang Trisno, M.SIE, dan Dr. Aip Saripudin, M.T</span></p>Bambang Trisno<br>Aip Saripudin', '2024-05-14 21:56:15', '2024-05-21 20:06:04');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (97, 1, 5, 36, 4, 1, 1, 1, 1, '<p style=\"margin:0\">Telah dilaksanakannya Pre-Defense pada Jumat, 17 Mei 2024 yang dimulai pada pukul 10.00 sampai 11.00. Sidang dihadiri oleh Bapak Erik Haritman selaku dosen pembimbing, Ibu Siscka Elvyanti , Bapak Resa Pramudita, dan Bapak Agus Heri Setya Budi sebagai dosen penguji. Terdapat revisi penulisan skripsi yang diberikan oleh dosen penguji. Sidang berjalan dengan lancar dan masukan dari dosen penguji dicatat dengan baik.<br></p>', '2024-05-14 21:57:44', '2024-05-19 15:10:27');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (98, 1, 24, 36, 4, 11, 1, 1, 1, '<p style=\"margin:0\">Pre-Defense pada Jumat, 17 Mei 2024 telah terlaksana dengan baik. Dimulai pukul 10.10 dan berakhir pada 11.14 ( 64 menit ). Dihadiri oleh Bapak Aip Saripudin selaku dosen pembimbing, Ibu Budi Mulyanti, Ibu Silmi Ath Thahirah Al Azhi, dan Bapak Muhammad Adli Rizqullah sebagai dosen penguji. Masukan dosen penguji dicatat dengan baik dan draft skripsi akan segera diperbaiki.</p>', '2024-05-14 22:01:59', '2024-05-19 13:01:07');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (99, 1, 272, 36, 2, 11, 1, 1, 1, '<p style=\"margin:0\">Sidang skripsi tertutup telah dilaksanakan pada hari Jumat, 17 Mei 2024 pukul 08.00-09.00. Sidang berlangsung sangat lancar, dengan semua dosen penguji beserta dosen pembimbing menghadiri sidang. Terdapat beberapa catatan yang perlu diluruskan terkait penulisan. Diskusi, kritik, dan saran dari para dosen penguji dan pembimbing memberikan arahan bagi diri saya untuk memperbaiki karya tulis saya menjadi lebih baik.</p>', '2024-05-14 22:30:27', '2024-05-21 14:18:14');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (100, 1, 311, 35, 1, 1, 1, 1, 1, '<p style=\"margin:0\">Sidang tertutup dilaksanakan pada tanggal 7 Juni 2024 pukul 07.00-08.00, dihadiri oleh dosen penguji:</p><p style=\"margin:0\">1. Bapak Dr. Yadi Mulyadi, M.T.</p><p style=\"margin:0\">2. Bapak Dr. Erik Haritman, S.Pd., M.T</p><p style=\"margin:0\">Beberapa masukan setelah sidang dilaksanakan, diantaranya:</p><p style=\"margin:0\">1. Tinjau lebih lanjut mengenai penggunaan lampu yang bisa dipakai.</p><p style=\"margin:0\">2. Tinjau lebih lanjut mengenai sensor yang digunakan untuk pengimplementasian.</p><p style=\"margin:0\">3. Tinjau lebih lanjut mengenai penggunaan daya lampu.</p><p style=\"margin:0\">4. Menambahkan resiko/kekurangan penggunaan sistem kontrol terhadap PJU dan dibandingkan dengan resiko/kekurangan PJU konvensional.</p>', '2024-05-16 14:57:38', '2024-06-10 09:48:57');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (101, 1, 305, 35, 3, 2, 1, 1, 1, '<p style=\"margin:0\">Sidang Pre-Defense telah dilakukan sesuai dengan tanggal dan jam yang telah dijadwalkan. Sidang dilakukan dengan lancar, disertai dengan masukan dari beberapa penguji agar skripsi yang dibuat menjadi lebih baik dan sesuai dengan pedoman yang ada.&nbsp;</p>', '2024-05-16 14:58:00', '2024-06-09 14:32:16');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (102, 1, 315, 35, 4, 1, 1, 1, 1, '<p style=\"margin:0\">Sidang tertutup dilaksanakan pada tanggal 7 Juni 2024 pukul 10.00-11.00, dihadiri oleh dosen penguji:</p><p style=\"margin:0\">1. Bapak&nbsp;Dr. Aip Saripudin, M.T.</p><p style=\"margin:0\">2. Bapak&nbsp;<span lang=\"EN-US\" style=\"line-height: 150%;\">Iwan\nKustiawan, S.Pd., M.T., Ph.D.&nbsp;</span><br><br>3.&nbsp;Ir.\nHj. Arjuni Budi Pantjawati, M.T.</p><p style=\"margin:0\">Beberapa masukan setelah sidang dilaksanakan, diantaranya:</p><p style=\"margin:0\">1. Perbaikan judul skripsi, abstrak, pendahuluan, dan kesimpulan</p><p style=\"margin:0\">2. Perbaikan mengenai tata letak penulisan mengenai isi yang ada di skripsi</p><p style=\"margin:0\">3. Tinjau lebih lanjut mengenai kurikulum 2013 revisi dengan kurikulum merdeka.</p><p style=\"margin:0\">4. Tinjau lebih lanjut mengenai apakah bisa dilakukan di tingkat yang lebih awal seperti dari SD<br><br>5. Masih ada subjektivitas dalam penyusunan</p>', '2024-05-16 14:58:19', '2024-06-10 11:12:00');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (103, 1, 314, 35, 3, 1, 1, 1, 1, '<p style=\"margin:0\">Saat sidang tertutup (pre defense) yang dilaksanakan pada hari jum\'at, tanggal 7 Juni 2024 pukul 09.00 - 10.00 WIB yang dihadiri oleh:</p><p style=\"margin:0\">1. Prof. Dr. Ade Gafar Abdullah, S.Pd., M.Si. (Dosen Pembimbing)</p><p style=\"margin:0\">2. Dr. Aip Saripudin, S.Si., M.T. (Dosen Penguji 1)</p><p style=\"margin:0\">3. Agus Heri Setya Budi, S.T., M.T. (Dosen Penguji 2)</p><p style=\"margin:0\">4. M. Adli Rizqulloh, S.Pd., M.T. (Dosen Penguji 3)</p><p style=\"margin:0\">Terdapat beberapa masukan dalam sidang tersebut, diantaranya:</p><p style=\"margin:0\">1. Pertimbangkan kembali kata \"Perbandingan\" dalam judul dikarenakan tidak ditujukan untuk membandingkan hasil yang terbaik diantara kedua metode/algoritma yang digunakan.</p><p style=\"margin:0\">2. Penambahan kesimpulan bagian analisis sensitivitas pada bab 5.1. Simpulan.</p><p style=\"margin:0\">3. Penambahan penjelasan proses penemuan kriteria-kriteria yang dipertimbangkan didapat dari jurnal apa saja.</p><p style=\"margin:0\">4. Berikan penomoran pada persamaan-persamaan kedua algoritma.</p><p style=\"margin:0\">5. Perbaikan flowchart di fungsi TOPSIS dan SAW.</p>', '2024-05-16 15:51:40', '2024-06-10 19:59:30');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (104, 1, 300, 35, 2, 3, 1, 1, 1, '<p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:150%\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Sidang\ntertutup dilaksanakan pada tanggal 7 Juni 2024 pukul 08.00-089.00, dihadiri\noleh Dosen Penguji:<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin-top:0cm;margin-right:0cm;\nmargin-bottom:0cm;margin-left:18.0pt;mso-add-space:auto;text-indent:-18.0pt;\nline-height:150%;mso-list:l0 level1 lfo2\"><!--[if !supportLists]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif;\nmso-fareast-font-family:&quot;Times New Roman&quot;\">1.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Bapak\nDr. Ir. Dadang Lukman Hakim, M.T.<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin-top:0cm;margin-right:0cm;\nmargin-bottom:0cm;margin-left:18.0pt;mso-add-space:auto;text-indent:-18.0pt;\nline-height:150%;mso-list:l0 level1 lfo2\"><!--[if !supportLists]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif;\nmso-fareast-font-family:&quot;Times New Roman&quot;\">2.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Bapak\nDr. Aip Saripudin, S.Si., M.T.<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin-top:0cm;margin-right:0cm;\nmargin-bottom:0cm;margin-left:18.0pt;mso-add-space:auto;text-indent:-18.0pt;\nline-height:150%;mso-list:l0 level1 lfo2\"><!--[if !supportLists]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif;\nmso-fareast-font-family:&quot;Times New Roman&quot;\">3.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Ibu\nMariya Al Qibtiya, M.T., <o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:150%\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Dan\nDosen Pembimbing:<o:p></o:p></span></p><p class=\"MsoListParagraph\" style=\"margin-top:0cm;margin-right:0cm;margin-bottom:\n0cm;margin-left:18.0pt;mso-add-space:auto;text-indent:-18.0pt;line-height:150%;\nmso-list:l1 level1 lfo1\"><!--[if !supportLists]--><span style=\"font-size:12.0pt;\nline-height:150%;font-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:\n&quot;Times New Roman&quot;\">1.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;\n</span></span><!--[endif]--><span style=\"font-size:12.0pt;line-height:150%;\nfont-family:&quot;Times New Roman&quot;,serif\">Bapak Agus Heri Setya Budi, S.T., M.T.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:150%\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Beberapa\nmasukan setelah sidang dilaksanakan, diantaranya:<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin-top:0cm;margin-right:0cm;\nmargin-bottom:0cm;margin-left:18.0pt;mso-add-space:auto;text-align:justify;\ntext-indent:-18.0pt;line-height:150%;mso-list:l2 level1 lfo3\"><!--[if !supportLists]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif;\nmso-fareast-font-family:&quot;Times New Roman&quot;\">1.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Penulisan\nketerangan Gambar dan Tabel dalam skripsi tidak menggunakan spasi, contohnya\nseperti berikut “Gambar 1.1 dan Tabel 2.1”<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin-top:0cm;margin-right:0cm;\nmargin-bottom:0cm;margin-left:18.0pt;mso-add-space:auto;text-align:justify;\ntext-indent:-18.0pt;line-height:150%;mso-list:l2 level1 lfo3\"><!--[if !supportLists]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif;\nmso-fareast-font-family:&quot;Times New Roman&quot;\">2.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Tinjau\nlebih lanjut keterkaitan dari ketiga sungai yaitu Sungai Cikapundung, Sungai\nCisangkuy dan Sungai Citarum dalam menyebabkan bencana banjir daerah Dayeuh\nKolot Kota Bandung. <o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin-top:0cm;margin-right:0cm;\nmargin-bottom:0cm;margin-left:18.0pt;mso-add-space:auto;text-align:justify;\ntext-indent:-18.0pt;line-height:150%;mso-list:l2 level1 lfo3\"><!--[if !supportLists]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif;\nmso-fareast-font-family:&quot;Times New Roman&quot;\">3.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Alat\nyang dirancang harus dapat melakukan monitoring&nbsp;\nterhadap potensi terjadinya banjir dalam kondisi apapun seperti Normal,\nSiaga, Waspada, dan Awas. <o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin-top:0cm;margin-right:0cm;\nmargin-bottom:0cm;margin-left:18.0pt;mso-add-space:auto;text-align:justify;\ntext-indent:-18.0pt;line-height:150%;mso-list:l2 level1 lfo3\"><!--[if !supportLists]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif;\nmso-fareast-font-family:&quot;Times New Roman&quot;\">4.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Informasi\npenyampaian peringatan dini terjadinya banjir pada aplikasi <i>WhatsApp\nMessenger</i> terlalu banyak, disarankan untuk ditampilkan yang penting nya\nsaja seperti status peringatan bencana banjir dan waktu yang dibutuhkan dalam\nmelakukan evakuasi. <o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin-top:0cm;margin-right:0cm;\nmargin-bottom:0cm;margin-left:18.0pt;mso-add-space:auto;text-align:justify;\ntext-indent:-18.0pt;line-height:150%;mso-list:l2 level1 lfo3\"><!--[if !supportLists]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif;\nmso-fareast-font-family:&quot;Times New Roman&quot;\">5.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Kata\n“Metode Star Topology” termasuk sebuah topologi jaringan yang umum digunakan\ndalam instalasi computer/PC, disarankan untuk dihilangkan saja dalam judul\nkarena metode itu merupakan bukan suatu teknologi yang asing lagi dalam\njaringan sebuah komputer. <o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin-top:0cm;margin-right:0cm;\nmargin-bottom:0cm;margin-left:18.0pt;mso-add-space:auto;text-align:justify;\ntext-indent:-18.0pt;line-height:150%;mso-list:l2 level1 lfo3\"><!--[if !supportLists]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif;\nmso-fareast-font-family:&quot;Times New Roman&quot;\">6.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Penulisan\nkoma yang tadinya “.” diganti menjadi “,”, karena bahasa yang digunakan dalam\npenyusunan skripsi menggunakan bahasa Indonesia <o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin-top:0cm;margin-right:0cm;\nmargin-bottom:0cm;margin-left:18.0pt;mso-add-space:auto;text-align:justify;\ntext-indent:-18.0pt;line-height:150%;mso-list:l2 level1 lfo3\"><!--[if !supportLists]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif;\nmso-fareast-font-family:&quot;Times New Roman&quot;\">7.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Gambar\nkurva grafik pada BAB IV, disarankan untuk dihilangkan karenan tidak\nmempresentasikan apa-apa. <o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin-top:0cm;margin-right:0cm;\nmargin-bottom:0cm;margin-left:18.0pt;mso-add-space:auto;text-align:justify;\ntext-indent:-18.0pt;line-height:150%;mso-list:l2 level1 lfo3\"><!--[if !supportLists]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif;\nmso-fareast-font-family:&quot;Times New Roman&quot;\">8.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Tabel\nyang dibuat jika melebihi page/halaman itu harus dibuat lagi kepala tabelnyadi lembaran kertas kerja yang baru. <i><o:p></o:p></i></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin-top:0cm;margin-right:0cm;\nmargin-bottom:0cm;margin-left:18.0pt;mso-add-space:auto;text-align:justify;\ntext-indent:-18.0pt;line-height:150%;mso-list:l2 level1 lfo3\"><!--[if !supportLists]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif;\nmso-fareast-font-family:&quot;Times New Roman&quot;\">9.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Kesimpulan\npada skripsi terlalu banyak, sedangkan rumusan masalah dan tujuan penelitian\nhanya ada satu, disarankan sebaiknya untuk kesimpulan harus selaras dengan rumusan\nmasalah dan tujuan penelitian. <i><o:p></o:p></i></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin-top:0cm;margin-right:0cm;\nmargin-bottom:0cm;margin-left:18.0pt;mso-add-space:auto;text-align:justify;\ntext-indent:-18.0pt;line-height:150%;mso-list:l2 level1 lfo3\"><!--[if !supportLists]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif;\nmso-fareast-font-family:&quot;Times New Roman&quot;\">10.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp; </span></span><!--[endif]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Dalam\nmelakukan presentasi hindari menggunakan kata “mungkin” karena bersifat\nketidakpastian dan ketidakyakinan pada alat yang kita buat atau hal lainnya<i><o:p></o:p></i></span></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin-top:0cm;margin-right:0cm;\nmargin-bottom:0cm;margin-left:18.0pt;mso-add-space:auto;text-align:justify;\ntext-indent:-18.0pt;line-height:150%;mso-list:l2 level1 lfo3\"><!--[if !supportLists]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif;\nmso-fareast-font-family:&quot;Times New Roman&quot;\">11.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp; </span></span><!--[endif]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Penulisan\nkata hubung “Mikrokontroler” harus selaras jangan di potong secara\nberbeda-beda. <i><o:p></o:p></i></span></p><p style=\"margin:0\">\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n</p><p class=\"MsoNormal\" style=\"margin-bottom:0cm;line-height:150%\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">&nbsp;</span></p>', '2024-05-16 17:02:18', '2024-06-11 07:45:39');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (105, 1, 318, 35, 2, 1, 1, 1, 1, '<p style=\"margin:0\">Sidang tertutup dilaksanakan pada tanggal 7 Juni 2024 pukul 08.00-09.00, dihadiri oleh dosen penguji dan pembimbing:</p><p style=\"margin:0\">1. Prof. Dr. Ade Gafar Abdullah, S.Pd., M.Si.</p><p style=\"margin:0\">Bapak Dr. Yadi Mulyadi, S.Pd., M.T.</p><p style=\"margin:0\">2. Bapak Dr. Erik Haritman, S.Pd., M.T.</p><p style=\"margin:0\">3. Ibu Silmi Ath Thahirah Al Azhima, S.T., M.T.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Beberapa masukan setelah sidang dilaksanakan, diantaranya:</p><p style=\"margin:0\">1. Hapus beberapa penjelasan eksplisit metode penelitian, cukup prosedur penelitian saja berbentuk flowchart, karena membuat sebuah prototipe</p><p style=\"margin:0\">2. Menambahkan spesifikasi agar lebih afdol pembuatan prototipe-nya</p><p style=\"margin:0\">3. Menambahkan penjelasan lebih lanjut mengenai text to speech</p><p style=\"margin:0\">4. Menambahkan Batasan Masalah</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Selebihnya siding tertutup dilaksanakan dengan baik, dan alhamdulillah tanpa hambatan.</p>', '2024-05-16 17:20:31', '2024-06-10 11:41:51');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (106, 1, 323, 38, 4, 3, 1, 1, 1, '<p style=\"margin:0\">Saat sidang tertutup (pre defense) yang dilaksanakan pada hari jum\'at, tanggal 14 Juni 2024 pukul 10.00 - 11.00 WIB yang dihadiri oleh:</p><p style=\"margin:0\">1. Prof. Dr. Ade Gafar Abdullah, S.Pd., M.Si. (Dosen Pembimbing)</p><p style=\"margin:0\">2. Agus Heri Setya Budi, S.T., M.T. (Dosen Penguji 1)</p><p style=\"margin:0\">3. Ir. Hj. Arjuni Budi Pantjawati, M.T (Penguji 2)</p><p style=\"margin:0\">4. Resa Pramudita, S.Pd., M.T (Dosen Penguji 3)</p><p style=\"margin:0\">Terdapat beberapa masukan dalam sidang tersebut, diantaranya:</p><p style=\"margin:0\">1. Perubahan Kata HRES menjadi \"Hybrid Renewable Energy System\" dalam judul.</p><p style=\"margin:0\">2. Penambahan kesimpulan bagian tujuan pada bab 5.1. Simpulan.</p><p style=\"margin:0\">3. Perbaikan penomoran peringkat pada hasil akhir kriteria.</p><p style=\"margin:0\">4. Perbaikan posisi penempatan Gambar 4.1 dan seterusnya.</p><p style=\"margin:0\">5. Perbaikan Daftar isi yang tidak sesuai dengan pedoman.</p><p style=\"margin:0\">6. Perbaikan sitasi yang tidak sesuai dengan pedoman.</p>', '2024-05-22 11:47:02', '2024-06-15 13:06:00');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (107, 1, 313, 38, 3, 3, 1, 1, 1, '<p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\"><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\">Saat sidang tertutup (pre defense) yang dilaksanakan pada hari jum\'at, tanggal 14 Juni 2024 pukul 09.00 - 10.00 WIB yang dihadiri oleh:</span></p><p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\" style=\"text-indent: 15px;\"><span class=\"selectable-text copyable-text x1sdyfia xss6m8b\" style=\"white-space-collapse: preserve;\">1.</span><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\"> Prof. Dr. Ade Gafar Abdullah, S.Pd., </span><span class=\"selectable-text copyable-text\" style=\"color: var(--link); white-space-collapse: preserve;\">M.Si</span><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\">. (Dosen Pembimbing)</span></p><p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\" style=\"text-indent: 15px;\"><span class=\"selectable-text copyable-text x1sdyfia xss6m8b\" style=\"white-space-collapse: preserve;\">2.</span><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\"> Ir. Hj. Arjuni Budi Pantjawati, M.T. (Dosen Penguji 1)</span></p><p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\" style=\"text-indent: 15px;\"><span class=\"selectable-text copyable-text x1sdyfia xss6m8b\" style=\"white-space-collapse: preserve;\">3.</span><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\"> Dr. Bambang Trisno, M.SIE. (Dosen Penguji 2)</span></p><p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\" style=\"text-indent: 15px;\"><span class=\"selectable-text copyable-text x1sdyfia xss6m8b\" style=\"white-space-collapse: preserve;\">4.</span><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\"> Resa Pramudita, S.Pd., M.T. (Dosen Penguji 3)</span></p><p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\"><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\">Terdapat beberapa masukan dalam sidang tersebut, diantaranya:</span></p><p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\" style=\"text-indent: 15px;\"><span class=\"selectable-text copyable-text x1sdyfia xss6m8b\" style=\"white-space-collapse: preserve;\">1.</span><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\"> Pertimbangkan kembali pemilihan kalimat di Abstak</span></p><p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\" style=\"text-indent: 15px;\"><span class=\"selectable-text copyable-text x1sdyfia xss6m8b\" style=\"white-space-collapse: preserve;\">2.</span><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\"> Rapihkan ukuran gambar Flowchart</span></p><p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\" style=\"text-indent: 15px;\"><span class=\"selectable-text copyable-text x1sdyfia xss6m8b\" style=\"white-space-collapse: preserve;\">3.</span><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\"> Berikan kalimat penjelasan pada gambar hasil urutan prioritas</span></p>', '2024-05-22 13:34:28', '2024-06-15 12:30:48');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (108, 1, 325, 39, 2, 1, 1, 1, 1, '<p style=\"margin:0\">Saya sudah melaksanakan sidang tgl 31 Mei 2024. Terdapat beberapa masukan dari penguji untuk dijadikan revisi. Revisi sudah diselesaikan pada tanggal 2 Juli 2024.<br></p>', '2024-05-24 11:32:40', '2024-06-25 12:05:50');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (109, 1, 317, 38, 2, 3, 1, 1, 1, '<p style=\"margin:0\">Saat sidang tertutup (pre defense) yang dilaksanakan pada hari jum\'at, tanggal 14 Juni 2024 pukul 08.00 - 09.00 WIB yang dihadiri oleh:</p><p style=\"margin:0\">1. Prof. Dr. Ade Gafar Abdullah, S.Pd., M.Si. (Dosen Pembimbing)</p><p style=\"margin:0\">2. Dr. Yadi Mulyadi, M.T (Dosen Penguji 1)</p><p style=\"margin:0\">3. Dr. Aip Saripudin, S.Si, M.T (Penguji 2)</p><p style=\"margin:0\">4. Prof. Dr. Tuti Suartini M.Pd (Dosen Penguji 3)</p><p style=\"margin:0\">Terdapat beberapa masukan dalam sidang tersebut, diantaranya:</p><p style=\"margin:0\">1. Meluruskan pada bagian latar belakang</p><p style=\"margin:0\">2. Penambahan kesimpulan bagian rumusan pada bab 5.1. Simpulan.</p><p style=\"margin:0\">3. Perbaikan sitasi pada bagian hasil wawancara menggunakan kaidah bahas baku.</p><p style=\"margin:0\">4. Penambahan penjelasan pada Gambar.</p><p style=\"margin:0\">5. Perbaikan Daftar isi yang tidak sesuai dengan pedoman.</p><p style=\"margin:0\">6. Penambahan penulisan pada metode penelitian.</p><p style=\"margin:0\">7. Penambahan penjelasan pada tabel 3.1.</p>', '2024-05-27 10:49:47', '2024-06-21 08:18:33');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (110, 1, 312, 35, 2, 2, 1, 1, 1, '<p style=\"margin:0\">Telah mengikuti sidang tertutup (Pre-Defense) pada hari Jum\'at, 07 Juni 2024.</p>', '2024-05-28 11:40:48', '2024-06-11 08:12:19');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (111, 1, 413, 35, 4, 2, 1, 1, 1, '<p style=\"margin:0\">Sidang tertutup dilaksanakan pada tanggal 7 Juni 2024 pukul 10.00-11.00, dihadiri oleh dosen penguji:</p><p style=\"margin:0\">1. Bapak Dr. Ir. H. Dadang Lukman Hakim, M.T.</p><p style=\"margin:0\">2. Bapak Dr. Ir. Maman Somantri, S.Pd., M.T.</p><p style=\"margin:0\">3. Bapak Dr. Bambang Trisno, M.SIE.</p><p style=\"margin:0\">Beberapa masukan setelah sidang dilaksanakan, diantaranya:</p><p style=\"margin:0\">1. Menambahkan catatan mengenai mekanisme prioritas relai yang bekerja saat terjadi gangguan.</p><p style=\"margin:0\">2. Menambahkan gambar mengenai rangkaian relai ke PMT.</p><p style=\"margin:0\">3. Tinjau lebih lanjut mengenai temuan pada GFR sisi 70 kV.</p><p style=\"margin:0\">4. Menambahkan gambar Gardu Induk dan bay trafo 3 ke dalam metode penelitian dan bukan di lampiran.</p>', '2024-05-30 11:54:59', '2024-06-10 10:20:25');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (112, 1, 320, 38, 2, 2, 1, 1, 1, '<p style=\"margin:0\">Saat sidang tertutup (pre defense) yang dilaksanakan pada hari jum\'at, tanggal 14 Juni 2024 pukul 08.00 - 09.00 WIB yang dihadiri oleh:</p><p style=\"margin:0\">1. Dr.Ir. Maman Somantri, S.Pd., M.T. (Dosen Pembimbing)</p><p style=\"margin:0\">2. Dr. Tasma Sucita, M.T. (Dosen Penguji 1)</p><p style=\"margin:0\">3. Resa Pramudita, S.Pd., M.T. (Dosen Penguji 2)</p><p style=\"margin:0\">4. Muhammad Adli Rizqulloh, S.Pd., M.T (Dosen Penguji 3)</p><p style=\"margin:0\">Terdapat beberapa masukan dalam sidang tersebut, diantaranya:</p><p style=\"margin:0\">1. Perbaikan pada abstrak dengan menunjukan tujuan penenelitian, metode penelitian, hasil penelitian sesuai dengan pendoman UPI</p><p style=\"margin:0\">2. Perbaikan pada BAB I</p><p style=\"margin:0\">- Pada latar belakang menambahkan sitasi yang kurang</p><p style=\"margin:0\">- pada rumusan dan tujuan penelitian terlalu general agar diperbaiki menjadi 3 rumusan masalah dan 3 tujuan penelitian</p><p style=\"margin:0\">2. perbaikan pada BAB II</p><p style=\"margin:0\">- gambar komponen yang hilang dan menyertakan sumber gambar</p><p style=\"margin:0\">-Penambahan silabus mata pelajaran instalasi penerangan listrik</p><p style=\"margin:0\">- penelitian yang relevan ditambahkan penjelasan&nbsp;</p><p style=\"margin:0\">3. Perbaikan pada BAB IV dan V</p><p style=\"margin:0\">-nama responden harap disamarkan dikarenakan etika penulisan karya ilmiah</p><p style=\"margin:0\">- pada pembahasan menjadi 3 pembahasan penelitian sesuai dengan tujuan penelitian</p><p style=\"margin:0\">-pada simpulan menjadi 3 sesuai dengan tujuan penelitian</p>', '2024-05-30 15:32:44', '2024-06-15 13:28:16');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (113, 1, 319, 38, 1, 3, 1, 1, 1, '<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span lang=\"IN\" style=\"line-height: 150%;\">Pada saat sidang tertutup (pre-defense) saya yang\ndilaksanakan pada hari Jum\'at, tanggal 14 Juni 2024 pukul 07.00 - 08.00 WIB\nyang dihadiri oleh :<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"line-height: 150%;\"><span lang=\"IN\" style=\"line-height: 150%;\">1. Prof. Dr. Ade Gafar Abdullah, S.Pd., M.Si. (Dosen\nPembimbing)<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"line-height: 150%;\"><span lang=\"IN\" style=\"line-height: 150%;\">2. Dr. Aip Saripudin, S.Si., M.T. (Dosen Penguji 1)<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"line-height: 150%;\"><span lang=\"IN\" style=\"line-height: 150%;\">3. Dr. Yadi Mulyadi, M.T. (Dosen Penguji 2)<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"line-height: 150%;\"><span lang=\"IN\" style=\"line-height: 150%;\">Terdapat beberapa masukan dalam sidang tersebut,\ndiantaranya :<o:p></o:p></span></p><ol><li style=\"line-height: 150%;\"><span lang=\"IN\" style=\"line-height: 150%;\">Bab I terlalu panjang perlu dibagi menjadi beberapa\nbagian.<o:p></o:p></span></li><li style=\"line-height: 150%;\"><span lang=\"IN\" style=\"line-height: 150%;\">Kesalahan pengetikan harus diperbaiki, dan sumber\nsitasi harus dari penulis yang jelas.<o:p></o:p></span></li><li style=\"line-height: 150%;\"><span lang=\"IN\" style=\"line-height: 150%;\">Diagram alir prosedur penelitian diubah menjadi Bahasa\nIndonesia.<o:p></o:p></span></li><li style=\"line-height: 150%;\"><span lang=\"IN\" style=\"line-height: 150%;\">Tambah kalimat penjelasan pada gambar dan tabel yang\nada, agar pembaca dapat lebih memahami isinya.<o:p></o:p></span></li><li style=\"line-height: 150%;\"><span lang=\"IN\" style=\"line-height: 150%;\">Penulisan keterangan gambar dan tabel ditulis di atasnya.</span></li><li style=\"line-height: 150%;\"><span lang=\"IN\" style=\"line-height: 150%;\">Pada kesimpulan, bagi menjadi 3 poin penjelasan yang\nmencakup semua aspek dari rumusan masalah yang telah dibuat.<font face=\"Times New Roman, serif\"><span style=\"font-size: 12pt;\"><o:p></o:p></span></font></span></li></ol>', '2024-05-30 19:21:24', '2024-06-15 15:15:35');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (114, 1, 373, 38, 3, 2, 1, 1, 1, '<p style=\"margin:0\">Sidang tertutup dilaksanakan hari Jumat, 14 Juni 2024 pada pukul 09.00-10.00 WIB yang bertempat di Lab. Elektronika Dasar, dihadiri oleh dosen penguji:</p><p style=\"margin:0\">1. Bapak Dr. Aip Saripudin, M.T.</p><p style=\"margin:0\">2. Bapak Muhammad Adli Rizqulloh S.Pd., M.T.</p><p style=\"margin:0\">Beberapa masukan setelah sidang dilaksanakan, diantaranya:</p><p style=\"margin:0\">1. Meninjau kembali Undang-Undang Guru dan Dosen, dan memperbaiki konteks kalimat pada pengertian guru profesional.</p><p style=\"margin:0\">2. Memperbaiki format tabel dan grafik.</p>', '2024-06-06 11:10:46', '2024-06-21 13:34:52');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (115, 1, 381, 38, 2, 1, 1, 1, 1, '<p style=\"margin:0\">Sidang tertutup dilaksanakan pada tanggal 14 Juni 2024 pukul 08.00-09.00, dihadiri oleh dosen penguji:</p><p style=\"margin:0\">1. Bapak Agus Heri Setya Budi., S.T., M.T.</p><p style=\"margin:0\">2. Bapak Dr. Erik Haritman.S.PD., M.T.</p><p style=\"margin:0\">Beberapa masukan setelah sidang dilaksanakan, diantaranya:</p><p style=\"margin:0\">1. Menambahkan metode dalam abstrak.</p><p style=\"margin:0\">2. Menjelaskan lebih detail terkait <i>Timing Diagram.</i></p><p style=\"margin:0\">3. Penulisan Kapital pada judul \"IOT\" menjadi \"IoT\"</p><p style=\"margin:0\">4. Penyederhanaan abstrak bahasa indonesia ke dalam bahasa inggris lebih mudah dipahami.<br><br>5. <i>Flow Chart Hardware&nbsp;</i>&nbsp;dan <i>Software&nbsp;</i>lebih dijelaskan kembali.<br><br>6. Isi Konfigurasi bisa diperinci kembali.</p>', '2024-06-06 22:45:24', '2024-06-21 10:34:17');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (116, 1, 410, 47, 3, 2, 1, 1, 1, '<p style=\"margin:0\">Revisi dari Dosen Penguji Tasma Sucita</p><ul><li>Sesuaikan penulisan dengan pedoman penulisan karya ilmiah UPI</li></ul><p style=\"margin:0\">Revisi dari Dosen Penguji Erik Haritman</p><ul><li>Perbaiki penulisan paragraf di bagian latar belakang</li><li>Perbaiki keterangan spesifikasi PNETLAB</li><li>Tambahkan uji stabilitas server&nbsp;</li><li>Perjelas mengenai uji validitas ahli materi</li><li>Perbaiki poin instrumen untuk respons siswa pada aspek pembelajaran no 1</li><li>Perbaiki posisi penempatan gambar di halaman 53</li></ul><p style=\"margin:0\">Revisi dari Dosen Pembimbing Aip Saripudin</p><ul><li>Perbaiki Cover</li><li>Perbaiki penulisan keterangan tabel</li><li>Perbaiki penulisan &gt;</li><li>Perbaiki penulisan daftar pustaka</li></ul>', '2024-06-08 08:37:40', '2024-07-26 19:59:32');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (117, 1, 223, 41, 1, 11, 1, 1, 1, '<p style=\"margin:0\">Telah selesai dilaksanakan pukul 7:00 - 8:00 di ruang dosen 12-13 dengan dosen penguji Dr. Tasma Sucita, M.T. dan Dr. Yadi Mulyadi, M.T.</p>', '2024-06-09 14:56:07', '2024-06-13 17:54:36');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (118, 1, 56, 41, 2, 10, 1, 1, 1, '<p style=\"margin:0\">13 Juni 2024</p><p style=\"margin:0\">Kehadiran:</p><p style=\"margin:0\">Dosen Pembimbing : Bapak Dr. H. Bambang Trisno, MSIE.</p><p style=\"margin:0\">Dosen Penguji 1: Dr. Elih Mulyana, M.Si</p><p style=\"margin:0\">Dosen Penguji 2: Prof. Dr. Jaja Kustija, M.Sc.</p><p style=\"margin:0\">Dosen Penguji 3: Dr. Erik Haritman, S.Pd., M.T.</p>', '2024-06-10 12:46:14', '2024-06-14 18:14:31');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (119, 1, 242, 41, 2, 11, 1, 1, 1, '<p style=\"margin:0\">Tanggal : 6 Juni 2024</p><p style=\"margin:0\">Dosen Pembimbing: Dr. Ir. H. Dadang Lukman Hakim, M.T</p><p style=\"margin:0\">Dosen Penguji : Dr.&nbsp; Yadi Mulyadi, M.T., Dr. Tasma Sucita, M.T&nbsp;</p><p style=\"margin:0\">&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p>', '2024-06-10 13:11:54', '2024-06-13 11:16:59');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (120, 1, 403, 38, 4, 2, 1, 1, 1, '<p style=\"margin:0\">Sidang tertutup dilaksanakan pada tanggal 14 Juni 2024 pukul 10.00-11.00, dihadiri oleh dosen penguji:</p><p style=\"margin:0\">1.&nbsp;<span style=\"color: inherit; font-size: 1rem;\">Bapak Dr. Ir. Maman Somantri, S.Pd., M.T.</span></p><p style=\"margin:0\">2. Bapak Dr. Bambang Trisno, M.SIE.</p><p style=\"margin:0\">Beberapa masukan setelah sidang dilaksanakan, diantaranya:</p><p style=\"margin:0\">1. Merevisi abstrak</p><p style=\"margin:0\">2. Menambahkan gambar pada Bab II</p><p style=\"margin:0\">3. Tinjau lebih lanjut mengenai sistem distribusi</p><p style=\"margin:0\">4. Tambah gambar rangkaian OCR dan GFR</p>', '2024-06-10 14:11:40', '2024-06-21 09:00:25');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (121, 1, 326, 47, 2, 2, 1, 1, 1, '<p class=\"MsoNormal\" style=\"text-align:justify;text-justify:inter-ideograph\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif\">Saat\nsidang tertutup (pre defense) yang dilaksanakan pada hari kamis, tanggal 25 Juli\n2024 pukul 08.00 - 09.00 WIB yang dihadiri oleh:<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-align:justify;text-justify:inter-ideograph\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif\">1.\nDr. Ir. Maman Somantri, S.Pd., M.T., IPU. (Dosen Pembimbing)<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-align:justify;text-justify:inter-ideograph\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif\">2.\nWasimudin Surya, S.T., M.T. (Dosen Penguji 1)<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-align:justify;text-justify:inter-ideograph\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif\">3.\nProf. Dr. Jaja Kustija, M.Sc. (Dosen Penguji 2)</span></p><p class=\"MsoNormal\" style=\"text-align:justify;text-justify:inter-ideograph\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif\">Terdapat\nbeberapa masukan dalam sidang tersebut, diantaranya:<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-align:justify;text-justify:inter-ideograph\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif\">1.\nPerbaiki lagi kata penghubung di judul skripsi terkait Persepsi guru dan siswa\npenggunaan trainer IPL <i>IoT.<o:p></o:p></i></span></p><p class=\"MsoNormal\" style=\"text-align:justify;text-justify:inter-ideograph\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif\">2.\nPerbaiki lagi atau lebih dimatangkan lagi kata bahasanya di Abstrak.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-align:justify;text-justify:inter-ideograph\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif\">3.\nPeneliti harus liner dari tujuan penelitian, kajian pustaka, dasar teori.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-align:justify;text-justify:inter-ideograph\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif\">4.\nTabel di bagian lampirannya harus diperbaiki lagi.<o:p></o:p></span></p><p style=\"margin:0\">\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n</p><p class=\"MsoNormal\" style=\"text-align:justify;text-justify:inter-ideograph\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif\">5.\nDi bagian kesimpulanya harus diperbaiki kata bahasanya tidak boleh ada kata\nyang diulang kembali.<o:p></o:p></span></p>', '2024-06-25 14:29:42', '2024-07-28 12:10:45');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (122, 1, 241, 48, 1, 3, 1, 1, 1, '<p style=\"margin:0\">Sidang skripsi pada tanggal 23/07/2024 berhasil dilaksanakan dengan lancar.</p><p style=\"margin:0\"><span style=\"font-size: 16px;\"><br></span></p><p style=\"margin:0\">Pada kesempatan sidang kali ini dihadiri oleh :</p><p style=\"margin:0\">1. Bu Budi Mulyanti selaku pembimbing dan moderator</p><p style=\"margin:0\">2. Pak didin selaku penguji 1</p><p style=\"margin:0\">3. Pak enjang selaku penguji 2</p><p style=\"margin:0\">4. Pak wawan sebagai penguji 3 tetapi berhalangan hadir.</p><p style=\"margin:0\">Notulensi yang didapat dalam sidang ini sebagai berikut.&nbsp;</p><p style=\"margin:0\">1. Penulisan pada bab 1, 3, dan daftar pustaka tidak rapih.</p><p style=\"margin:0\">2. Kesalahan pada keterangan tabel yang berada dibawah.</p><p style=\"margin:0\">3. Flowchart tidak sesuai dengan kaidah.</p><p style=\"margin:0\">4. Beberapa kata dalam bahasa inggris tidak dicetak miring</p><p style=\"margin:0\">5. Terlalu banyaknya gambar pada tabel pengujian.</p><p style=\"margin:0\">6. Pengujian kalibrasi alat belum ada sertifikasinya.</p><p style=\"margin:0\">7. Kurangnya asumsi penulis pada penelitian ini.</p>', '2024-06-26 13:50:05', '2024-08-20 21:32:32');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (123, 1, 408, 47, 2, 1, 1, 1, 1, '<p dir=\"ltr\"><span ;=\"\"> </span>Pada hari kamis, tanggal 25 Juli 2024 telah dilaksanakan sidang skripsi atas nama mahasiswa:</p><p dir=\"ltr\">Nama: Cathy Dewi Azizah </p><p dir=\"ltr\">NIM: 2008805</p><p dir=\"ltr\">Judul Skripsi: \"Sistem Pemberian Nutrisi Tanaman Otomatis\"</p><p dir=\"ltr\">Sidang skripsi ini dilaksanakan di ruang&nbsp; laboratorium Elektronika Industri FPTK Universitas Pendidikan Indonesia.</p><p dir=\"ltr\">Anggota Sidang :</p><p dir=\"ltr\">Dosen Pembimbing : Dr. Erik Haritman, S.Pd., M.T.</p><p dir=\"ltr\">Dosen penguji : Ir. Arjuni Budi Pantjawati, M.T., Dr. Aip Saripudin, M.T, Wawan Purnama, S.Pd., M.Si.</p><p dir=\"ltr\">Pertanyaan dan masukan dari Penguji : <br>\n- Bapak Wawan Purnama<br>\nPertanyaan :<br>\n1. Apakah masalah yang dihadapi petani terkait tanaman pakcoi? Apakah ada data terkait kendala pemberian nutrisi dalam pemberian manual?<br>\n2. Apa kejelasan tujuan penelitian ini? Apakah dapat menyelesaikan masalah?<br>\n3. Faktor apa yang menyebabkan hasil tanaman yang otomatis dan manual sama?<br>\nMasukan : <br>\nDalam membuat penelitian harus jelas masalah yang memang, untuk referensi jangan hanya satu tapi harus ada dari beberapa referensi terkait.</p><p dir=\"ltr\">- Bapak Aip Saripudin<br>\nMasukan : <br>\n1. Rumusan masalah harus sama dengan tujuan penelitian<br>\n2. Tabel dan gambar harus dipanggil pada paragraf<br>\n3. Harus ada data setelah penelitian untuk membuktikan apakah sistem dapat menjaga kelembaban tanah.</p><p dir=\"ltr\">- Ibu Arjuni Budi Pantjawati<br>\nPertanyaan : <br>\n1. Kenapa disiram setiap hari? Bukannya pemberian pupuk tidak setiap hari?<br>\n2. Kenapa rentang waktunya hanya 3 jam?<br>\nMasukan : <br>\n1. Judul terlalu umum<br>\n2. jika alat diuji harus sampai ke batasnya<br>\n3. Sistem ini hanya tentang penjadwalan saja, tidak untuk budidaya nya.<br>\n4. Algoritma harus jelas<br>\n5. Cari tahu kembali kenapa penyimpanan RTC sampai 1 menit tiap harinya.<br>\n6. Ini hanya membantu petani agar tidak menyiram saja, tidak dengan membantu hasil panen.</p><p style=\"margin:0\">\n\n\n\n\n\n\n\n\n\n\n</p><p dir=\"ltr\">Demikian hasil dari sidang tertutup yang telah dilaksanakan, dibuat dengan sebenar-benarnya.&nbsp;<br></p>', '2024-06-27 09:48:06', '2024-07-31 17:30:24');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (124, 1, 400, 47, 3, 1, 1, 1, 1, '<p style=\"margin:0\">Saat sidang tertutup (pre defense) yang dilaksanakan pada hari Kamis, tanggal 25 Juli 2024 pukul 09.00 - 10.00 WIB yang dihadiri oleh:</p><p style=\"margin:0\">1. 1. Bapak Wasimudin Surya, S.T., M.T. (Dosen Penguji 1)&nbsp;</p><p style=\"margin:0\">2. Bapak Prof. Dr. Jaja Kustija, M.Sc. (Dosen Penguji 2)&nbsp;</p><p style=\"margin:0\">3. Bapak Wawan Purnama, S. Pd., M.Si (Dosen Penguji 3)&nbsp;</p><p style=\"margin:0\">4. Dr. Ir. MamanSomantri, S.Pd., M.T. IPU (Dosen Pembimbing)</p>', '2024-06-28 11:13:36', '2024-07-27 21:11:11');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (125, 1, 333, 47, 4, 1, 1, 1, 1, '<p class=\"MsoNormal\">Sidang tertutup dilaksanakan pada tanggal 25 Juli 2024 pukul\n10.00-11.00, dihadiri oleh dosen penguji:<o:p></o:p></p><p class=\"MsoNormal\">1. Ibu Ir. Arjuni Budi Pantjawati, M.T.<o:p></o:p></p><p class=\"MsoNormal\">2. Bapak Dr. Aip Saripudin, S.Si, M.T.<o:p></o:p></p><p class=\"MsoNormal\">Beberapa masukan setelah sidang dilaksanakan, diantaranya:<o:p></o:p></p><p class=\"MsoNormal\">1. Memperbaiki Penulisan Sesuai dengan Kaidah Kebahasaan<o:p></o:p></p><p class=\"MsoNormal\">2. Meninjau lebih lanjut metode yang digunakan<o:p></o:p></p><p class=\"MsoNormal\">3. Menambahkan catatan mengenai pembaruan alat yang dibuat<o:p></o:p></p><p class=\"MsoNormal\">4. Membandingkan Hasil Pembacaan Sensor dengan Website The Weather\nChannel<o:p></o:p></p><p class=\"MsoNormal\">5. Menambahkan catatan proses kalibrasi sensor dan modul<o:p></o:p></p><p style=\"margin:0\">\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n</p><p class=\"MsoNormal\">6. Menambahkan catatan mengenai faktor yang mempengaruhi\nkinerja alat<o:p></o:p></p>', '2024-06-30 06:15:00', '2024-07-26 13:37:01');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (126, 1, 9, 48, 2, 3, 1, 1, 1, '<p style=\"margin:0\"><br></p>', '2024-07-01 12:32:56', '2024-08-09 14:10:20');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (127, 1, 324, 51, 2, 1, 1, 1, 1, '<p style=\"margin:0\">Sidang tertutup dilaksanakan pada tanggal 12 Juli 2024 pukul 08.00-09.00, dihadiri oleh dosen penguji:</p><p style=\"margin:0\">1. Ibu Mariya Al-Qibtiya, S.Si.,M.T.</p><p style=\"margin:0\">2. Bapak Dr.Aip Saripudin, M.T.</p><p style=\"margin:0\">3. Bapak Dr. Ir. H. Dadang Lukman</p><p style=\"margin:0\">Beberapa masukan setelah sidang dilaksanakan, diantaranya:</p><p style=\"margin:0\">1. Diskusikan kembali dengan dosen pembimbing mengenai Judul Skripsi</p><p style=\"margin:0\">2. Perbaikan mengenai penulisan Bahasa asing dan Bahasa serapan</p><p style=\"margin:0\">3. Perbaikan pada ucapan terimakasih, tujuan yang sesuai dengan rumusan masalah, dan keterangan pada gambar&nbsp;</p><p style=\"margin:0\">4. Menambahkan keterangan pada table yang dipakai, beberapa simbol yang perlu diberi keterangan</p>', '2024-07-01 16:54:50', '2024-07-16 09:45:46');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (128, 1, 383, 51, 2, 2, 1, 1, 1, '<p style=\"margin:0\">Izin melaporkan bahwa saya sudah melakukan PRE-DEFENSE, dan ada beberapa revisi yang sudah dikerjakan/diperbaiki, saya juga sudah menyiapkan artikel untuk PUBLIC-DEFENSE.<br></p>', '2024-07-04 06:56:18', '2024-08-12 07:40:08');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (129, 1, 398, 47, 4, 2, 1, 1, 1, '<p style=\"margin:0\">Saat sidang tertutup (pre defense) yang dilaksanakan pada hari Kamis, tanggal 25 Juli 2024 pukul 10.00 - 11.00 WIB yang dihadiri oleh:</p><p style=\"margin:0\">1. Dr. Tasma Sucita, S.T., M.T. (Dosen Pembimbing)</p><p style=\"margin:0\">2. Dr. Ir. Maman Somantri, S.Pd., M.T. (Dosen Penguji 1)</p><p style=\"margin:0\">3. Resa Pramudita S.Pd., M.T. (Dosen Penguji 2)</p><p style=\"margin:0\">Terdapat beberapa masukan dalam sidang tersebut, diantaranya:</p><p style=\"margin:0\">1. Penambahan kata \"Pengukuran\" dalam judul dikarenakan tidak ditunjukan hasil yang terbaik.</p><p style=\"margin:0\">2. Perbaikan kata \"di\" yang menunjukan tempat pada judul apakah harus huruf kapital atau tidak.</p><p style=\"margin:0\">3. Penambahan penjelasan penelitian yang relevan dengan memperhatikan bagaimana cara menguukurnya dan yang diukurnya apa.</p>', '2024-07-04 16:14:05', '2024-08-13 20:42:12');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (130, 1, 341, 51, 3, 3, 1, 1, 1, '<p style=\"margin:0\">Sidang tertutup sudah dikerjakan dengan baik dan terdapat beberapa perbaikan yang sudah dikerjakan</p>', '2024-07-04 16:34:03', '2024-08-13 14:26:34');
