INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (30, 52, 59, '<p style=\"margin:0\">Izin menjawab pak, mikrotik sebagai pengatur lalulintas data jaringan internet.</p>', '2023-09-29 02:37:40', '2023-09-29 02:37:40');
INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (31, 52, 59, '<p style=\"margin:0\">Konsepnya iot akan sebagai pembuat user otomatis yang dipengaruhi oleh koin yang masuk melalui sensor. Dan data itu akan akan diteruskan melalui telnet untuk membuat variabel data global dan run script di mikrotik.</p>', '2023-09-29 02:38:36', '2023-09-29 02:38:36');
INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (32, 52, 59, '<p style=\"margin:0\">Dibandingkan dengan raspberry pi. Konsep penggunaan iot dan mikrotik lebih murah dengan sistem jaringan internet lebih andal</p>', '2023-09-29 02:39:16', '2023-09-29 02:39:16');
