INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (161, 95, 215, '<p style=\"margin:0\">assalamualaikum ar wb pak/bu, selamat sore mohon maaf menggangu waktunya izin bertanya apakah ini sudah tersubmit?ternyata saya lupa untuk pijit submit pak/bu baru kecek tadi padahal saya sudah buat dari tanggal 12 Okt, bagaimana ya pak/bu apakah masih&nbsp;bisa&nbsp;diterima?<br></p>', '2023-10-14 09:49:42', '2023-10-14 09:49:42');
