INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (330, 125, 91, '<p style=\"margin:0\">dari sisi teknologi mengontrol gerbang menggunakan bluetooth mungkin terlalu sederhana, bisa ditambahkan fitur IoT didalamnya ?&nbsp;</p>', '2023-10-19 16:08:39', '2023-10-19 16:08:39');
INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (331, 125, 91, '<p style=\"margin:0\"><span style=\"color: rgb(55, 65, 81); font-family: Söhne, ui-sans-serif, system-ui, -apple-system, &quot;Segoe UI&quot;, Roboto, Ubuntu, Cantarell, &quot;Noto Sans&quot;, sans-serif, &quot;Helvetica Neue&quot;, Arial, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; white-space-collapse: preserve; background-color: rgb(247, 247, 248);\">Meskipun ada bagian \"Referensi\" di akhir halaman, tampaknya daftar pustaka belum lengkap. Pastikan untuk menyertakan semua sumber yang Anda kutip dalam proposal Anda.</span><br></p>', '2023-10-19 16:09:09', '2023-10-19 16:09:09');
INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (332, 125, 91, '<p style=\"margin:0\"><span style=\"color: rgb(55, 65, 81); font-family: Söhne, ui-sans-serif, system-ui, -apple-system, &quot;Segoe UI&quot;, Roboto, Ubuntu, Cantarell, &quot;Noto Sans&quot;, sans-serif, &quot;Helvetica Neue&quot;, Arial, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; white-space-collapse: preserve; background-color: rgb(247, 247, 248);\">Anda perlu memberikan penjelasan teknis yang lebih rinci mengenai bagaimana sistem Anda bekerja, terutama bagian kontrol bluetooth dan mikrokontroller serta IoT jika menggunakan teknologi tersebut.</span><br></p>', '2023-10-19 16:10:35', '2023-10-19 16:10:35');
INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (333, 125, 91, '<p style=\"margin:0\">Saran Judul \" Perancangan Sistem Gerbang Otomatis Berbasis Teknologi Bluetooth dan IoT\"</p>', '2023-10-19 16:16:21', '2023-10-19 16:16:21');
INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (334, 98, 91, '<p style=\"margin:0\">Tolong anda Jelaskan dalam proposal mengapa anda memilih LoRa sebagai protokol komunikasi ? jelaskan keunggulannya dan mengapa anda menggunakan alat tersebut dibanding platform lain ?</p>', '2023-10-19 16:22:09', '2023-10-19 16:22:09');
