INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (380, 116, 229, 'izin jawab pak, pertama terkait media sosial saya revisi penggunaan diksi nya dengan konten digital, karena jika membahas media sosial maka kita harus meneliti juga objek yang bersangkutan tapi untuk system yang saya buat ini lebih cenderung ke perancangan dan untuk tahapan pertama ini tidak akan di kaitkan ke media sosial dulu karena dikhawatirkan menjadi suatu hal yang tidak bisa saya tangani jadi saya memutuskan untuk cenderung ke perancangan system ini dengan subjek percobaan diambil dari konten digital yang ada di internet bukan lagi difokuskan ke media sosial', '2023-10-24 02:26:04', '2023-10-24 02:26:04');
INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (381, 116, 229, 'dan alasan fiksasi lama karena perlu riset yang mendalam tentang pembuatan system ini karena sedikitnya referensi khusus nya jurnal jurnal yang berbahasa indonesia, dan untuk revisi udah selesai pak.', '2023-10-24 02:30:13', '2023-10-24 02:30:13');
