INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (873, 109, 187, '<p style=\"margin:0\">Mohon maaf pak saya sudah melaksanakan sidang pada tanggal 4 Mei 2024, untuk pengajuan jadwal serta artikel penelitian sudah di ACC oleh dosen pembimbing. karna pada saat pengajuan propsal saya sedang melaksanakan magang di Yogyakarta sedangkan dosen pembimbing saya pada saat itu bilang terkait penelitian Tugas Akhir jalan saja dahulu hingga selesai. nah itu bagaimana ya pak kasusnya?<br></p>', '2024-05-31 13:15:54', '2024-05-31 13:15:54');
INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (880, 431, 187, '<p style=\"margin:0\">Assalamualaikum Wr. Wb.<br>Selamat siang bapak/Ibu dosen dan sebelumnya mohon maaf mengganggu aktivitasnya. Izin menyampaikan pada topik penelitian skripsi yang saya ajukan menggunakan topik penelitian dari dosen yaitu bapak Muhammad adli Rizqulloh dengan tema Trainer Op-amp, dan pada saat itu saya sudah melakukan diskusi terkait penelitian tersebut dan katanya silahkan ajukan saja proposalnya pada arsys<br>Sekian atas informasinya yang dapat saya sampaikan, atas perhatiannya saya ucapkan terimakasih banyak<br></p>', '2024-06-03 12:50:47', '2024-06-03 12:50:47');
