INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (911, 439, 94, '<p style=\"margin:0\">proposalnya masih banyak typo. Sitasi juga ada yang belum konsisten.&nbsp; Kemudian, sebutkan saja target akurasi dari studi ini dan improvement nya dibanding studi sebelumnya. Kemudian highlight inovasi apa&nbsp; dari deep learning yang digunakan untuk meningkatkan performa prediksi sensor microcantilever tersebut.<br></p>', '2024-07-04 11:29:57', '2024-07-04 11:29:57');
