INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (966, 478, 14, '<p style=\"margin:0\">akses tidak bisa dibuka.<br><br>dari hasil diskusi terakhir ttg topik ini, jadi urgensinya apa? monitoring tekanan ban ini dilakukan pada saat apa?</p>', '2024-09-19 14:36:42', '2024-09-19 14:36:42');
