INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (1080, 460, 14, '<p style=\"margin:0\">1. sitasi masih kurang</p><p style=\"margin:0\">2. state of the art blm menjelaskan kontribusi yang akan dilakukan dipenelitian km apa. Keterbaharuan dari penelitian km apa jika dibandingkan dengan penelitian sebelumnya?</p>', '2024-09-26 13:00:40', '2024-09-26 13:00:40');
