INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (1094, 482, 8, '<p style=\"margin:0\">Analisis yang sering dilakukan pada sistem kendali menggunakan simulink biasanya adalah analisis kestabilan, pada kasus mesin annealing biasanya diperlukan&nbsp; &nbsp;kelajuan \npanas dan kelajuan pendinginan (bukan ke kestabilan temperatur), coba di jelaskan lagi terkait analisis-nya dalam hal apa, variabel2 input dan outnya apa saja?</p>', '2024-09-29 18:47:00', '2024-09-29 18:47:00');
INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (1098, 463, 8, '<p style=\"margin:0\">judul tidak jelas, coba lebih fokus/ terarah lagi.<br>Latar belakang, tujuan dan metode yang digunakan harus lebih jelas</p>', '2024-09-29 18:53:29', '2024-09-29 18:53:29');
INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (1099, 462, 8, '<p style=\"margin:0\">judul tidak jelas, coba lebih fokus/ terarah lagi. Belum terlihat hubungan antara sistem manajemen (menggunakan CNN) dengan kontrol Robot arm.<br>Latar belakang, tujuan dan metode yang digunakan harus lebih jelas. CNN di gunakan dalam hal apa? demikian juga robot arm digunakan untuk apa? kaitkan dengan latar belakang-nya.</p>', '2024-09-29 19:46:56', '2024-09-29 19:46:56');
