INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (1104, 490, 93, '<ul><li>terdapat kekeliruan pada susunan sitasi proposal&nbsp;</li><li>alat konvensional fermentasi yoghurt tidak dijelaskan secara rinci, dan secara tiba-tiba menjelaskan bahwa alat konvesional fermentasi yoghurt memiliki kekurangan.</li><li>ukuran/jenis font yang digunakan tidak seragam; bisa dilihat pada pendekatan pemecahan masalah.</li><li>penjelasan pada pendekatan pemecahan masalah belum dijelaskan dengan baik</li><li>pada bagian state of the art dan kebaruan, sebaiknya cari 3-5 penelitian terkait dan jelaskan secara rinci hal apa yang dilakukan dari penelitian tersebut.</li><li>metode R &amp; D yang diajukan dapat dihubungkan dengan topik penelitian yang diajukan. sehingga tidak hanya menjelaskan tentang definisi dari metode R &amp; D.</li><li>tujuan penelitian yang akan dilakukan tidak dijelaskan dengan baik.&nbsp;</li></ul>', '2024-10-02 17:35:09', '2024-10-02 17:35:09');
INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (1107, 483, 95, '<p style=\"margin:0\">\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n</p><p class=\"MsoListParagraphCxSpFirst\" style=\"text-indent:-18.0pt;mso-list:l0 level1 lfo1\"><span lang=\"IN\" style=\"font-family:Symbol;mso-fareast-font-family:Symbol;mso-bidi-font-family:\nSymbol\"><span style=\"mso-list:Ignore\">·<span style=\"font:7.0pt &quot;Times New Roman&quot;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n</span></span></span><span lang=\"IN\">“Sistem Kontrol Peningkatan\nKualitas” tidak jelas. Sistem kontrol seperti apa? Mengapa sistem kontrol ini\nperlu IoT? Apa perbedaannya dengan IoT pada sistem lain?</span></p>\n\n<p class=\"MsoListParagraphCxSpMiddle\" style=\"text-indent:-18.0pt;mso-list:l0 level1 lfo1\"><span lang=\"IN\" style=\"font-family:Symbol;mso-fareast-font-family:Symbol;mso-bidi-font-family:\nSymbol\"><span style=\"mso-list:Ignore\">·<span style=\"font:7.0pt &quot;Times New Roman&quot;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n</span></span></span><span lang=\"IN\">Penggunaan Arduino (jenis atau\nmodelnya perlu dituliskan) bukan hal yang baru dalam IoT</span></p>\n\n<p class=\"MsoListParagraphCxSpMiddle\" style=\"text-indent:-18.0pt;mso-list:l0 level1 lfo1\"><span lang=\"IN\" style=\"font-family:Symbol;mso-fareast-font-family:Symbol;mso-bidi-font-family:\nSymbol\"><span style=\"mso-list:Ignore\">·<span style=\"font:7.0pt &quot;Times New Roman&quot;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n</span></span></span><span lang=\"IN\">Informasi mengenai sensor-sensor\napa saja yang akan digunakan sebaiknya juga disertakan pada proposal.</span></p>\n\n<p class=\"MsoListParagraphCxSpLast\" style=\"text-indent:-18.0pt;mso-list:l0 level1 lfo1\"><span lang=\"IN\" style=\"font-family:Symbol;mso-fareast-font-family:Symbol;mso-bidi-font-family:\nSymbol\"><span style=\"mso-list:Ignore\">·<span style=\"font:7.0pt &quot;Times New Roman&quot;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n</span></span></span><span lang=\"IN\">Strategi kontrol yang akan\ndigunakan perlu dituliskan (on-off, PID, ?)</span></p>\n\n\n\n\n\n<p style=\"margin:0\"><style>@font-face\n	{font-family:Wingdings;\n	panose-1:5 0 0 0 0 0 0 0 0 0;\n	mso-font-charset:77;\n	mso-generic-font-family:decorative;\n	mso-font-pitch:variable;\n	mso-font-signature:3 0 0 0 -2147483647 0;}@font-face\n	{font-family:\"Cambria Math\";\n	panose-1:2 4 5 3 5 4 6 3 2 4;\n	mso-font-charset:0;\n	mso-generic-font-family:roman;\n	mso-font-pitch:variable;\n	mso-font-signature:-536870145 1107305727 0 0 415 0;}@font-face\n	{font-family:Aptos;\n	panose-1:2 11 0 4 2 2 2 2 2 4;\n	mso-font-charset:0;\n	mso-generic-font-family:swiss;\n	mso-font-pitch:variable;\n	mso-font-signature:536871559 3 0 0 415 0;}p.MsoNormal, li.MsoNormal, div.MsoNormal\n	{mso-style-unhide:no;\n	mso-style-qformat:yes;\n	mso-style-parent:\"\";\n	margin-top:0cm;\n	margin-right:0cm;\n	margin-bottom:8.0pt;\n	margin-left:0cm;\n	line-height:107%;\n	mso-pagination:widow-orphan;\n	font-size:11.0pt;\n	font-family:\"Aptos\",sans-serif;\n	mso-ascii-font-family:Aptos;\n	mso-ascii-theme-font:minor-latin;\n	mso-fareast-font-family:Aptos;\n	mso-fareast-theme-font:minor-latin;\n	mso-hansi-font-family:Aptos;\n	mso-hansi-theme-font:minor-latin;\n	mso-bidi-font-family:\"Times New Roman\";\n	mso-bidi-theme-font:minor-bidi;\n	mso-font-kerning:1.0pt;\n	mso-ligatures:standardcontextual;\n	mso-ansi-language:IN;\n	mso-fareast-language:EN-US;}p.MsoListParagraph, li.MsoListParagraph, div.MsoListParagraph\n	{mso-style-priority:34;\n	mso-style-unhide:no;\n	mso-style-qformat:yes;\n	margin-top:0cm;\n	margin-right:0cm;\n	margin-bottom:8.0pt;\n	margin-left:36.0pt;\n	mso-add-space:auto;\n	line-height:107%;\n	mso-pagination:widow-orphan;\n	font-size:11.0pt;\n	font-family:\"Aptos\",sans-serif;\n	mso-ascii-font-family:Aptos;\n	mso-ascii-theme-font:minor-latin;\n	mso-fareast-font-family:Aptos;\n	mso-fareast-theme-font:minor-latin;\n	mso-hansi-font-f