INSERT INTO `arsys_research_supervise` (`id`, `research_id`, `supervisor_id`, `threader_id`, `status`, `topic`, `message`, `read`, `share`, `date_of_meeting`, `created_at`, `updated_at`) VALUES (1, 29, 30, 53, NULL, 'Progress Meeting', '<ul><li>Membahas ulang proposal skripsi</li><li>Membahas rujukan utama dan membuat slide rujukan utama untuk pertemuan selanjutnya</li></ul>', NULL, NULL, NULL, '2023-10-09 09:19:34', '2023-10-09 09:19:34');
INSERT INTO `arsys_research_supervise` (`id`, `research_id`, `supervisor_id`, `threader_id`, `status`, `topic`, `message`, `read`, `share`, `date_of_meeting`, `created_at`, `updated_at`) VALUES (2, 29, 30, 53, NULL, 'Progress Meeting', '<ul><li>Mempresentasikan slide rujukan utama</li><li>Membahas rujukan utama</li><li>Mencari rujukan mengenai hidden layers pada neural network</li></ul>', NULL, NULL, NULL, '2023-10-09 09:21:59', '2023-10-09 09:21:59');
INSERT INTO `arsys_research_supervise` (`id`, `research_id`, `supervisor_id`, `threader_id`, `status`, `topic`, `message`, `read`, `share`, `date_of_meeting`, `created_at`, `updated_at`) VALUES (3, 29, 30, 53, NULL, 'Progress Meeting', '<ul><li>Membahas isi bab 3 merujuk pada rujukan utama</li><li>Desain divais dijelaskan apakah adaptasi atau adopsi dari dari rujukan utama</li><li>Membuat workflow</li><li>Flowchart yang ada harus direvisi</li></ul>', NULL, NULL, NULL, '2023-10-09 09:24:51', '2023-10-09 09:24:51');
INSERT INTO `arsys_research_supervise` (`id`, `research_id`, `supervisor_id`, `threader_id`, `status`, `topic`, `message`, `read`, `share`, `date_of_meeting`, `created_at`, `updated_at`) VALUES (4, 26, 37, 38, NULL, 'Pengecekan bab 1-2', '<p>Melakukan pengecekan dari hasil kerja, yaitu bab 1-2</p>', NULL, NULL, NULL, '2023-10-12 06:49:19', '2023-10-12 06:49:19');
INSERT INTO `arsys_research_supervise` (`id`, `research_id`, `supervisor_id`, `threader_id`, `status`, `topic`, `message`, `read`, `share`, `date_of_meeting`, `created_at`, `updated_at`) VALUES (5, 31, 23, 52, NULL, 'Pemaparan progress laporan tugas akhir/skripsi', '<p>Note:</p><ul><li>Perbanyak baca literatur mengenai pengimplementasian konsep NOMA, channel coding (LDPC), teknik modulasi data (QAM) serta teknik multiple access</li><li>Tetapkan environment indoor untuk simulasinya</li><li>Kerjasama dengan mahasiswa lain mengenai script matlab</li></ul><p>Progress:</p><ul><li>Selesai menulis bab 1</li><li>Sudah menulis 70% bab 2 dan bab 3</li><li>Sudah bisa menggunakan fungsi ray tracing untuk melihat path loss sinyal dan juga power delay profile-nya<br></li></ul>', NULL, NULL, NULL, '2023-10-12 14:22:11', '2023-10-12 14:22:11');
INSERT INTO `arsys_research_supervise` (`id`, `research_id`, `supervisor_id`, `threader_id`, `status`, `topic`, `message`, `read`, `share`, `date_of_meeting`, `created_at`, `updated_at`) VALUES (6, 15, 34, 22, NULL, 'Bimbingan (review) Bab 1 Pendahuluan\nLatar belakang, Rumusan Masalah, Tujuan Penelitian, Manfaat Penelitian, dan Sistematika Penulisan', '<p>Bimbingan Bab 1 Pendahuluan, pembimbing memberikan beberapa poin penting hang harus saya lakukan :</p><p>1. Latar belakang penelitian yang diangkat tidak tercantum sehingga latar belakang yang sudah ada belum berkorelasi dengan rumusan masalah yang tertulis&nbsp;</p><p>2. Jika dirasa rumusan masalah terlalu banyak, pertimbangkan untuk mempersempit rumusan masalah yang diangkat</p><p>3. Menambahkan batasan masalah dari penelitian ini</p>', NULL, NULL, NULL, '2023-10-13 08:49:21', '2023-10-13 08:49:21');
INSERT INTO `arsys_research_supervise` (`id`, `research_id`, `supervisor_id`, `threader_id`, `status`, `topic`, `message`, `read`, `share`, `date_of_meeting`, `created_at`, `updated_at`) VALUES (7, 32, 57, 118, NULL, 'Bimbingan ke 1', '<p>Perbaikan bagian pendahuluan dan penentuan format jurnal yang akan digunakan.</p>', NULL, NULL, NULL, '2023-10-13 13:30:06', '2023-10-13 13:30:06');
INSERT INTO `arsys_research_supervise` (`id`, `research_id`, `supervisor_id`, `threader_id`, `status`, `topic`, `message`, `read`, `share`, `date_of_meeting`, `created_at`, `updated_at`) VALUES (8, 27, 31, 106, NULL, 'Memaparkan secara singkat mengenai sistem telegram', '<p>supervisor mengarahkan mahasiswa untuk membuat sistem telegram command untuk keperluan alur proposal skripsi pada arsys agar lebih mudah digunakan</p>', NULL, NULL, NULL, '2023-10-14 14:49:40', '2023-10-14 14:49:40');
INSERT INTO `arsys_research_supervise` (`id`, `research_id`, `supervisor_id`, `threader_id`, `status`, `topic`, `message`, `read`, `share`, `date_of_meeting`, `created_at`, `updated_at`) VALUES (9, 66, 67, 154, NULL, 'Bimbingan bab 1 - 3', '<ul><li>Ubah judul menjadi \"... berbasis GCP\"</li><li>jelaskan apa itu GCP di bab 2</li><li>kaji lebih dalam terkait topik AI yang digunakan pada penelitian ini di bab 2</li><li>tentukan metode penelitian: waterfall/ rnd</li><li>tentukan metode analisis data:&nbsp; kualitatif/ kuantitatif</li><li>cari tahu bagaimana cara mendapatkan data kelayakan dari sebuah sistem selain kuesioner</li><li>eksplor lebih jauh penggunaan AI di al quran</li><li>apakah bisa mendeteksi tajwid?</li></ul>', NULL, NULL, NULL, '2023-10-14 15:32:54', '2023-10-14 15:32:54');
INSERT INTO `arsys_research_supervise` (`id`, `research_id`, `supervisor_id`, `threader_id`, `status`, `topic`, `message`, `read`, `share`, `date_of_meeting`, `created_at`, `updated_at`) VALUES (10, 29, 29, 53, NULL, 'Progress Meeting', '<ul><li>Membahas langkah awal penelitian</li></ul>', NULL, NULL, NULL, '2023-10-16 11:24:34', '2023-10-16 11:24:34');
INSERT INTO `arsys_research_supervise` (`id`, `research_id`, `supervisor_id`, `threader_id`, `status`, `topic`, `message`, `read`, `share`, `date_of_meeting`, `created_at`, `updated_at`) VALUES (11, 11, 41, 17, NULL, 'membahas metode yang akan digunakan', '<p>- membahas metode yang akan digunakan</p>', NULL, NULL, NULL, '2023-10-18 02:15:53', '2023-10-18 02:15:53');
INSERT INTO `arsys_research_supervise` (`id`, `research_id`, `supervisor_id`, `threader_id`, `status`, `topic`, `message`, `read`, `share`, `date_of_meeting`, `created_at`, `updated_at`) VALUES (12, 68, 87, 172, NULL, 'Perbaikan Penulisan Skripsi', '<p>Memperbaiki penulisan skripsi untuk mengikuti pedoman skripsi Universitas Pendidikan Indonesia tahun 2019</p>', NULL, NULL, NULL, '2023-10-18 03:11:24', '2023-10-18 03:11:24');
INSERT INTO `arsys_research_supervise` (`id`, `research_id`, `supervisor_id`, `threader_id`, `status`, `topic`, `message`, `read`, `share`, `date_of_meeting`, `created_at`, `updated_at`) VALUES (13, 68, 86, 172, NULL, 'perbaikan Bab 1 dan Bab 2', '<p>perbaikan penulisan skripsi pada bab 1 dan bab 2</p>', NULL, NULL, NULL, '2023-10-18 03:20:51', '2023-10-18 03:20:51');
INSERT INTO `arsys_research_supervise` (`id`, `research_id`, `supervisor_id`, `threader_id`, `status`, `topic`, `message`, `read`, `share`, `date_of_meeting`, `created_at`, `updated_at`) VALUES (14, 29, 30, 53, NULL, 'Progress Meeting', '<ul><li><li>Membahas BAB 3 lebih lanjut</li><li>Coba buat flowchart penelitian secara umum</li><li>Coba buat plot dengan bantuan software seperti originlab</li></li></ul>', NULL, NULL, NULL, '2023-10-18 14:38:54', '2023-10-18 14:38:54');
INSERT INTO `arsys_research_supervise` (`id`, `research_id`, `supervisor_id`, `threader_id`, `status`, `topic`, `message`, `read`, `share`, `date_of_meeting`, `created_at`, `updated_at`) VALUES (15, 12, 47, 43, NULL, 'Pembahasan Bab 1 dan Bab 2', '<p>Pada Bab 1, membahas tentang rumusan masalah, tujuan dan batasan penelitian<br>Pada Bab 2, membahas tentang sub-bab yang harus dikurangi atau ditambahi serta dirapihkan susunannya</p>', NULL, NULL, NULL, '2023-10-19 05:18:31', '2023-10-19 05:18:31');
INSERT INTO `arsys_research_supervise` (`id`, `research_id`, `supervisor_id`, `threader_id`, `status`, `topic`, `message`, `read`, `share`, `date_of_meeting`, `created_at`, `updated_at`) VALUES (16, 57, 39, 115, NULL, 'Bimbingan ke-1', '<p>Melakukan perbaikan pendahuluan, diperlukan penambahan data dan referensi</p>', NULL, NULL, NULL, '2023-10-19 08:29:25', '2023-10-19 08:29:25');
INSERT INTO `arsys_research_supervise` (`id`, `research_id`, `supervisor_id`, `threader_id`, `status`, `topic`, `message`, `read`, `share`, `date_of_meeting`, `created_at`, `updated_at`) VALUES (17, 38, 40, 64, NULL, 'General discussion about research topic', 'Diskusi general terkait topik penelitian, tanya jawab terkait penelitian yang akan dilaksanakan seperti alasan penelitian, tujuan, manfaat, standar yang digunakan sehingga bisa mengetahui kondisi normal seperti apa, abnormal seperti apa.&nbsp;', NULL, NULL, NULL, '2023-10-19 08:52:29', '2023-10-19 08:52:29');
