INSERT INTO `arsys_research_supervise` (`id`, `research_id`, `supervisor_id`, `threader_id`, `status`, `topic`, `message`, `read`, `share`, `date_of_meeting`, `created_at`, `updated_at`) VALUES (25, 12, 46, 43, NULL, 'Pembahasan Bab 1 dan 2', '<p>Diskusi terkait pengubahan judul menjadi rancang bangun, lalu membahas terkait data, sistem yang dirancang, dan penulisan bab 1 dan 2</p>', NULL, NULL, NULL, '2023-10-22 15:50:18', '2023-10-22 15:50:18');
INSERT INTO `arsys_research_supervise` (`id`, `research_id`, `supervisor_id`, `threader_id`, `status`, `topic`, `message`, `read`, `share`, `date_of_meeting`, `created_at`, `updated_at`) VALUES (26, 66, 63, 154, NULL, 'Bimbingan pertama membahas Proposal', '<ul><li>Revisi pada proposal</li><li>Pengetahuan dasar-dasar ilmu yang dibutuhkan</li></ul>', NULL, NULL, NULL, '2023-10-23 08:17:48', '2023-10-23 08:17:48');
INSERT INTO `arsys_research_supervise` (`id`, `research_id`, `supervisor_id`, `threader_id`, `status`, `topic`, `message`, `read`, `share`, `date_of_meeting`, `created_at`, `updated_at`) VALUES (27, 39, 58, 131, NULL, 'Presentasi tentang proposal skripsi.\nMengganti judul skripsi menjadi simulasi.\nMerubah rumusan masalah, batasan masalah dan tujuan.\n', '<p>1. Merubah judul dari \"Perancangan Sistem Pendeteksi Mobil Satu Arah berbasis Computer Vision\" menjadi “Simulasi Sistem Pencegahan Kemacetan Melalui Pendeteksi Mobil p<span style=\"font-size: 1rem;\">ada Jalanan Sempit berbasis Computer Vision\"</span></p><p><span style=\"font-size: 1rem;\">2. Merubah hampir secara menyeluruh rumusan masalah, batasan masalah, dan tujuan.</span></p>', NULL, NULL, NULL, '2023-10-23 09:05:41', '2023-10-23 09:05:41');
INSERT INTO `arsys_research_supervise` (`id`, `research_id`, `supervisor_id`, `threader_id`, `status`, `topic`, `message`, `read`, `share`, `date_of_meeting`, `created_at`, `updated_at`) VALUES (28, 31, 23, 52, NULL, 'Progress Tugas Akhir', '<p>Progress:</p><ul><li>Menulis Bab 2 sampai 90%, dan sedang menulis Bab 3 sudah 50%</li><li>Mencoba menggunakan 2 receiver pada simulasi</li></ul><p>Problem:</p><ul><li>Terdapat error pada pengolahan data parameter perbandingan ketika menggunakan lebih dari dua receiver</li><li>Kode communication link untuk NOMA belum mengetahui</li><li>Belum menetapkan beberapa variabel seperti spesifikasi antena dan juga spesifikasi teknik pengkodean errornya (LDPC)</li><li>Bingung mencari dasar dari penentuan spesifikasi sistem</li></ul>', NULL, NULL, NULL, '2023-10-23 14:08:43', '2023-10-23 14:08:43');
INSERT INTO `arsys_research_supervise` (`id`, `research_id`, `supervisor_id`, `threader_id`, `status`, `topic`, `message`, `read`, `share`, `date_of_meeting`, `created_at`, `updated_at`) VALUES (29, 31, 22, 52, NULL, 'Progress Tugas Akhir', '<p>Memberikan Bab 1 untuk ditinjau</p>', NULL, NULL, NULL, '2023-10-23 14:09:45', '2023-10-23 14:09:45');
